export const PRAY_CANONICAL_DATA_V435930={"prayers":{"foundations_sign_of_cross":{"id":"foundations_sign_of_cross","title":"Sign of the Cross","titleFr":"Signe de la Croix","en":"In the name of the Father, and of the Son, and of the Holy Spirit. Amen.","la":"In nomine Patris, et Filii, et Spiritus Sancti. Amen.","fr":"Au nom du Père, et du Fils, et du Saint-Esprit. Amen.","source":"","sourceUrl":"","note":"","category":"essentials","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Sign of the Cross","witness":"Compendium of the Catechism of the Catholic Church · Appendix A","url":"https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_en.html","quality":"VERIFIED_PRIMARY","visibility":0,"adaptation":"VERBATIM","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_PRIMARY"},"note":"Common prayer; provenance retained internally and not shown by default."},"sourceAuditVersion":"35.7"},"foundations_our_father":{"id":"foundations_our_father","title":"Our Father","titleFr":"Notre Père","en":"Our Father, Who art in heaven, hallowed be Thy name; Thy kingdom come; Thy will be done on earth as it is in heaven. Give us this day our daily bread; and forgive us our trespasses, as we forgive those who trespass against us; and lead us not into temptation, but deliver us from evil. Amen.","la":"Pater noster, qui es in cælis, sanctificetur nomen tuum; adveniat regnum tuum; fiat voluntas tua, sicut in cælo et in terra. Panem nostrum quotidianum da nobis hodie; et dimitte nobis debita nostra, sicut et nos dimittimus debitoribus nostris; et ne nos inducas in tentationem, sed libera nos a malo. Amen.","fr":"Notre Père, qui êtes aux cieux, que votre nom soit sanctifié; que votre règne arrive; que votre volonté soit faite sur la terre comme au ciel. Donnez-nous aujourd’hui notre pain de chaque jour; pardonnez-nous nos offenses, comme nous pardonnons à ceux qui nous ont offensés; et ne nous laissez pas succomber à la tentation, mais délivrez-nous du mal. Amen.","source":"","sourceUrl":"","note":"","category":"essentials","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Our Father","witness":"Compendium of the Catechism of the Catholic Church · Appendix A","url":"https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_en.html","quality":"VERIFIED_PRIMARY","visibility":0,"adaptation":"VERBATIM","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_PRIMARY"},"note":"Common prayer; provenance retained internally and not shown by default."},"sourceAuditVersion":"35.7"},"foundations_hail_mary":{"id":"foundations_hail_mary","title":"Hail Mary","titleFr":"Je vous salue Marie","en":"Hail Mary, full of grace, the Lord is with thee; blessed art thou among women, and blessed is the fruit of thy womb, Jesus. Holy Mary, Mother of God, pray for us sinners, now and at the hour of our death. Amen.","la":"Ave Maria, gratia plena, Dominus tecum; benedicta tu in mulieribus, et benedictus fructus ventris tui, Iesus. Sancta Maria, Mater Dei, ora pro nobis peccatoribus, nunc et in hora mortis nostræ. Amen.","fr":"Je vous salue, Marie, pleine de grâce, le Seigneur est avec vous; vous êtes bénie entre toutes les femmes, et Jésus, le fruit de vos entrailles, est béni. Sainte Marie, Mère de Dieu, priez pour nous, pauvres pécheurs, maintenant et à l’heure de notre mort. Amen.","source":"","sourceUrl":"","note":"","category":"essentials","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Hail Mary","witness":"Compendium of the Catechism of the Catholic Church · Appendix A","url":"https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_en.html","quality":"VERIFIED_PRIMARY","visibility":0,"adaptation":"VERBATIM","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_PRIMARY"},"note":"Common prayer; provenance retained internally and not shown by default."},"sourceAuditVersion":"35.7"},"foundations_glory_be":{"id":"foundations_glory_be","title":"Glory Be","titleFr":"Gloire au Père","en":"Glory be to the Father, and to the Son, and to the Holy Spirit. As it was in the beginning, is now, and ever shall be, world without end. Amen.","la":"Gloria Patri, et Filio, et Spiritui Sancto. Sicut erat in principio, et nunc, et semper, et in sæcula sæculorum. Amen.","fr":"Gloire au Père, au Fils et au Saint-Esprit, comme il était au commencement, maintenant et toujours, et dans les siècles des siècles. Amen.","source":"","sourceUrl":"","note":"","category":"essentials","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Glory Be","witness":"Compendium of the Catechism of the Catholic Church · Appendix A","url":"https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_en.html","quality":"VERIFIED_PRIMARY","visibility":0,"adaptation":"VERBATIM","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_PRIMARY"},"note":"Common prayer; provenance retained internally and not shown by default."},"sourceAuditVersion":"35.7"},"foundations_apostles_creed":{"id":"foundations_apostles_creed","title":"Apostles’ Creed","titleFr":"Symbole des Apôtres","en":"I believe in God, the Father almighty, Creator of heaven and earth; and in Jesus Christ, His only Son, our Lord, Who was conceived by the Holy Spirit, born of the Virgin Mary, suffered under Pontius Pilate, was crucified, died and was buried; He descended into hell; on the third day He rose again from the dead; He ascended into heaven, and is seated at the right hand of God the Father almighty; from there He shall come to judge the living and the dead. I believe in the Holy Spirit, the holy Catholic Church, the communion of saints, the forgiveness of sins, the resurrection of the body, and life everlasting. Amen.","la":"Credo in Deum Patrem omnipotentem, Creatorem cæli et terræ. Et in Iesum Christum, Filium eius unicum, Dominum nostrum: qui conceptus est de Spiritu Sancto, natus ex Maria Virgine, passus sub Pontio Pilato, crucifixus, mortuus, et sepultus; descendit ad inferos; tertia die resurrexit a mortuis; ascendit ad cælos; sedet ad dexteram Dei Patris omnipotentis; inde venturus est iudicare vivos et mortuos. Credo in Spiritum Sanctum, sanctam Ecclesiam catholicam, Sanctorum communionem, remissionem peccatorum, carnis resurrectionem, vitam æternam. Amen.","fr":"Je crois en Dieu, le Père tout-puissant, Créateur du ciel et de la terre; et en Jésus-Christ, son Fils unique, notre Seigneur, qui a été conçu du Saint-Esprit, est né de la Vierge Marie, a souffert sous Ponce Pilate, a été crucifié, est mort et a été enseveli, est descendu aux enfers; le troisième jour est ressuscité des morts, est monté aux cieux, est assis à la droite de Dieu le Père tout-puissant, d’où il viendra juger les vivants et les morts. Je crois au Saint-Esprit, à la sainte Église catholique, à la communion des saints, à la rémission des péchés, à la résurrection de la chair et à la vie éternelle. Ainsi soit-il.","source":"","sourceUrl":"","note":"","category":"essentials","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Apostles’ Creed","witness":"Compendium of the Catechism of the Catholic Church · Appendix A","url":"https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_en.html","quality":"VERIFIED_PRIMARY","visibility":0,"adaptation":"VERBATIM","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_PRIMARY"},"note":"Common prayer; provenance retained internally and not shown by default."},"sourceAuditVersion":"35.7"},"sacrament_act_of_contrition":{"id":"sacrament_act_of_contrition","title":"Act of Contrition","titleFr":"Acte de contrition","en":"O my God, I am heartily sorry for having offended Thee, and I detest all my sins because of Thy just punishments, but most of all because they offend Thee, my God, who art all good and deserving of all my love. I firmly resolve with the help of Thy grace to sin no more and to avoid the near occasion of sin. Amen.","la":"Deus meus, ex toto corde pænitet me ómnium meórum peccatórum, eáque detéstor, quia peccándo, non solum pœnas a te iuste statútas proméritus sum, sed præsértim quia offéndi te, summum bonum, ac dignum qui super ómnia diligáris. Ídeo fírmiter propóno, adiuvánte grátia tua, de cétero me non peccatúrum peccandíque occasiónes próximas fugitúrum. Amen.","fr":"Mon Dieu, j’ai un très grand regret de vous avoir offensé parce que vous êtes infiniment bon et que le péché vous déplaît. Je prends la ferme résolution, avec le secours de votre sainte grâce, de ne plus vous offenser et de faire pénitence. Amen.","source":"","sourceUrl":"","note":"","category":"essentials","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Act of Contrition","witness":"Compendium of the Catechism of the Catholic Church · Appendix A","url":"https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_en.html","quality":"VERIFIED_PRIMARY","visibility":0,"adaptation":"VERBATIM","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_PRIMARY"},"note":"Common prayer; provenance retained internally and not shown by default."},"sourceAuditVersion":"35.7"},"foundations_act_of_faith":{"id":"foundations_act_of_faith","title":"Act of Faith","titleFr":"Acte de foi","en":"O my God, I firmly believe that you are one God in three divine Persons, Father, Son, and Holy Spirit. I believe that your divine Son became man and died for our sins and that he will come to judge the living and the dead. I believe these and all the truths which the Holy Catholic Church teaches because you have revealed them who are eternal truth and wisdom, who can neither deceive nor be deceived. In this faith I intend to live and die. Amen.","la":"Dómine Deus, firma fide credo et confíteor ómnia et síngula quæ sancta Ecclésia Cathólica propónit, quia tu, Deus, ea ómnia revelásti, qui es ætérna véritas et sapiéntia quæ nec fállere nec falli potest. In hac fide vívere et mori státuo. Amen.","fr":"Mon Dieu, je crois fermement toutes les vérités que vous m’avez révélées et que vous nous enseignez par votre sainte Église, parce que vous ne pouvez ni vous tromper, ni nous tromper. Dans cette foi, puis-je vivre et mourir. Amen.","source":"","sourceUrl":"","note":"","category":"essentials","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Act of Faith","witness":"Compendium of the Catechism of the Catholic Church · Appendix A","url":"https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_en.html","quality":"VERIFIED_PRIMARY","visibility":0,"adaptation":"VERBATIM","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_PRIMARY"},"note":"Replaced prior paraphrased wording with the official formulas."},"sourceAuditVersion":"35.7"},"foundations_act_of_hope":{"id":"foundations_act_of_hope","title":"Act of Hope","titleFr":"Acte d'espérance","en":"O Lord God, I hope by your grace for the pardon of all my sins and after life here to gain eternal happiness because you have promised it who are infinitely powerful, faithful, kind, and merciful. In this hope I intend to live and die. Amen.","la":"Dómine Deus, spero per grátiam tuam remissiónem ómnium peccatórum, et post hanc vitam ætérnam felicitátem me esse consecutúrum: quia tu promisísti, qui es infiníte potens, fidélis, benígnus, et miséricors. In hac spe vívere et mori státuo. Amen.","fr":"Mon Dieu, j’espère avec une ferme confiance que vous me donnerez, par les mérites de Jésus-Christ, votre grâce en ce monde et le bonheur éternel dans l’autre, parce que vous l’avez promis et que vous tenez toujours vos promesses. Dans cette foi, puis-je vivre et mourir. Amen.","source":"","sourceUrl":"","note":"","category":"essentials","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Act of Hope","witness":"Compendium of the Catechism of the Catholic Church · Appendix A","url":"https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_en.html","quality":"VERIFIED_PRIMARY","visibility":0,"adaptation":"VERBATIM","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_PRIMARY"},"note":"Replaced prior paraphrased wording with the official formulas."},"sourceAuditVersion":"35.7"},"foundations_act_of_love":{"id":"foundations_act_of_love","title":"Act of Love","titleFr":"Acte de charité","en":"O Lord God, I love you above all things and I love my neighbor for your sake because you are the highest, infinite and perfect good, worthy of all my love. In this love I intend to live and die. Amen.","la":"Dómine Deus, amo te super ómnia et próximum meum propter te, quia tu es summum, infinítum, et perfectíssimum bonum, omni dilectióne dignum. In hac caritáte vívere et mori státuo. Amen.","fr":"Mon Dieu, je vous aime de tout mon coeur et plus que tout, parce que vous êtes infiniment bon, et j’aime mon prochain comme moi-même pour l’amour de vous.","source":"","sourceUrl":"","note":"","category":"essentials","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Act of Love","witness":"Compendium of the Catechism of the Catholic Church · Appendix A","url":"https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_en.html","quality":"VERIFIED_PRIMARY","visibility":0,"adaptation":"VERBATIM","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_PRIMARY"},"note":"Replaced prior paraphrased wording with the official formulas."},"sourceAuditVersion":"35.7"},"foundations_guardian_angel":{"id":"foundations_guardian_angel","title":"Guardian Angel Prayer","titleFr":"Prière à l’Ange gardien","en":"Angel of God, my guardian dear, to whom God’s love commits me here, ever this day be at my side, to light and guard, to rule and guide. Amen.","la":"Ángele Dei, qui custos es mei, me, tibi commíssum pietáte supérna, illúmina, custódi, rege et gubérna. Amen.","fr":"Ange de Dieu, qui es mon gardien, et à qui j’ai été confié par la Bonté divine, éclaire-moi, défends-moi, conduis-moi et dirige-moi. Amen.","source":"","sourceUrl":"","note":"","category":"essentials","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Angel of God / Angele Dei","witness":"Compendium of the Catechism of the Catholic Church · Appendix A","url":"https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_en.html","quality":"VERIFIED_PRIMARY","visibility":0,"adaptation":"VERBATIM","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_PRIMARY"},"note":"Latin corrected to the official Angele Dei text."},"sourceAuditVersion":"35.7"},"foundations_grace_before_meals":{"id":"foundations_grace_before_meals","title":"Grace Before Meals","titleFr":"Bénédicité","en":"Bless us, O Lord, and these thy gifts, which we are about to receive from thy bounty, through Christ our Lord. Amen.","la":"Benedíc, Dómine, nos et haec tua dona, quae de tua largitáte sumus sumptúri, per Christum Dóminum nostrum. Amen.","fr":"Bénissez-nous, Seigneur, ainsi que les dons que nous allons recevoir de votre bonté, par le Christ notre Seigneur. Amen.","source":"","sourceUrl":"","note":"","category":"essentials","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Grace Before Meals","witness":"Baltimore Manual · 1888","url":"https://en.wikisource.org/wiki/A_Manual_of_Prayers_for_the_Use_of_the_Catholic_Laity/Morning_Prayers","quality":"VERIFIED_PRIMARY","visibility":0,"adaptation":"VERBATIM","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_SECONDARY"},"note":"The after-meal form in the app is a compact traditional form."},"sourceAuditVersion":"35.7"},"foundations_grace_after_meals":{"id":"foundations_grace_after_meals","title":"Grace After Meals","titleFr":"Grâces après le repas","en":"We give thee thanks, almighty God, for all thy benefits, who livest and reignest forever and ever. Amen. May the souls of the faithful departed, through the mercy of God, rest in peace. Amen.","la":"Agimus tibi gratias, omnipotens Deus, pro universis beneficiis tuis, qui vivis et regnas in saecula saeculorum. Amen. Et fidelium animae, per misericordiam Dei, requiescant in pace. Amen.","fr":"Nous te rendons grâce, Dieu tout-puissant, pour tous tes bienfaits. Toi qui vis et règnes pour les siècles des siècles. Amen. Et que les âmes de tous les fidèles défunts, par la miséricorde de Dieu, reposent en paix. Amen.","source":"","sourceUrl":"","note":"","category":"essentials","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Grace After Meals","witness":"Baltimore Manual · 1888","url":"https://en.wikisource.org/wiki/A_Manual_of_Prayers_for_the_Use_of_the_Catholic_Laity/Morning_Prayers","quality":"VERIFIED_PRIMARY","visibility":0,"adaptation":"ABRIDGED","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_SECONDARY"},"note":"The after-meal form in the app is a compact traditional form."},"sourceAuditVersion":"35.7"},"foundations_morning_offering":{"id":"foundations_morning_offering","title":"Morning Offering","titleFr":"Offrande du matin","en":"O Jesus, through the Immaculate Heart of Mary, I offer you my prayers, works, joys, and sufferings of this day for all the intentions of your Sacred Heart, in union with the Holy Sacrifice of the Mass throughout the world, for the salvation of souls, the reparation of sins, the reunion of all Christians, and in particular for the intentions of the Holy Father. Amen.","la":"Divínum Cor Iesu, per Immaculátum Cor Maríae, tibi óffero preces, ópera, gáudia et passiónes huius diéi, pro ómnibus intentiónibus sanctíssimi Cordis tui, in unióne cum sancto Missae Sacrifício per totum orbem terrárum celebráto, pro animárum salúte, peccatórum expiatíone, christiánorum reconciliatióne, et speciátim pro intentióne Summi Pontíficis. Amen.","fr":"Ô Jésus, par le Cœur Immaculé de Marie, je t’offre mes prières, œuvres, joies et souffrances de ce jour, en union avec le Saint Sacrifice de la Messe offert dans le monde entier, pour le salut des âmes, la réparation des péchés, l’union de tous les chrétiens, et en particulier pour les intentions du Saint-Père. Amen.","source":"Fr François-Xavier Gautrelet · 1844","sourceUrl":"https://www.usccb.org/prayers/morning-offering","note":"The Latin witness now matches the same traditional Apostleship-of-Prayer form as the English record; the Latin witness is secondary rather than an invented translation.","category":"essentials","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":true,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Morning Offering","witness":"USCCB · Catholic Household Blessings and Prayers, p. 48","url":"https://www.usccb.org/prayers/morning-offering","quality":"VERIFIED_PRIMARY","visibility":1,"adaptation":"VERBATIM","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_SECONDARY","fr":"VERIFIED_SECONDARY"},"note":"English is the USCCB form; French has a Catholic educational witness; Latin is an exact published devotional witness of the same traditional form.","latinWitness":"Glory Be Prayer · Oblatio Matutina (CBCP-attributed common-prayer witness)","latinUrl":"https://www.glorybeprayer.com/fil/prayers/morning-offering/"},"sourceAuditVersion":"41.4"},"foundations_prayer_of_adoration":{"id":"foundations_prayer_of_adoration","title":"My Lord and My God","titleFr":"Acte d’adoration","en":"My Lord and my God!","la":"Dominus meus et Deus meus!","fr":"Mon Seigneur et mon Dieu !","source":"","sourceUrl":"","note":"","category":"essentials","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"My Lord and my God","witness":"John 20:28","url":"https://bible.usccb.org/bible/john/20","quality":"VERIFIED_PRIMARY","visibility":0,"adaptation":"SCRIPTURE_QUOTATION","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_PRIMARY"},"note":"Short biblical acclamation; no visible source needed in ordinary use."},"sourceAuditVersion":"35.7"},"mass_confiteor":{"id":"mass_confiteor","title":"Confiteor","titleFr":"Confiteor","en":"I confess to Almighty God, to blessed Mary ever Virgin, to blessed Michael the Archangel, to blessed John the Baptist, to the holy Apostles Peter and Paul, to all the Saints, and to you Father, that I have sinned exceedingly, in thought, word and deed: through my fault, through my fault, through my most grievous fault. Therefore I beseech blessed Mary ever Virgin, blessed Michael the Archangel, blessed John the Baptist, the holy Apostles Peter and Paul, all the Saints, and thee Father, to pray to the Lord our God for me.","la":"Confíteor Deo omnipoténti, beátæ Maríæ semper Vírgini, beáto Michaéli Archángelo, beáto Ioánni Baptístæ, sanctis Apóstolis Petro et Paulo, ómnibus Sanctis, et tibi, pater: quia peccávi nimis cogitatióne, verbo et opere: mea culpa, mea culpa, mea máxima culpa. Ideo precor beátam Maríam semper Vírginem, beátum Michaélem Archángelum, beátum Ioánnem Baptístam, sanctos Apóstolos Petrum et Paulum, omnes Sanctos, et te, pater, orare pro me ad Dóminum, Deum nostrum.","fr":"Je confesse à Dieu tout-puissant, à la bienheureuse Marie toujours Vierge, à saint Michel Archange, à saint Jean-Baptiste, aux saints Apôtres Pierre et Paul, à tous les saints, et à vous, mon Père, que j’ai beaucoup péché par pensée, par parole et par action : c’est ma faute, c’est ma faute, c’est ma très grande faute. C’est pourquoi je supplie la bienheureuse Marie toujours Vierge, saint Michel Archange, saint Jean-Baptiste, les saints Apôtres Pierre et Paul, tous les saints, et vous, mon Père, de prier pour moi le Seigneur notre Dieu.","source":"Missale Romanum 1962 · Prayers at the Foot of the Altar","sourceUrl":"","note":"Traditional Roman Confiteor used in the 1962 Order of Mass; this is not the shortened postconciliar Confiteor.","category":"essentials"},"marian_hail_holy_queen":{"id":"marian_hail_holy_queen","title":"Hail Holy Queen (Salve Regina)","titleFr":"Salve Regina","en":"Hail, holy Queen, Mother of mercy, our life, our sweetness, and our hope. To thee do we cry, poor banished children of Eve; to thee do we send up our sighs, mourning and weeping in this valley of tears. Turn then, most gracious advocate, thine eyes of mercy toward us; and after this our exile, show unto us the blessed fruit of thy womb, Jesus. O clement, O loving, O sweet Virgin Mary.\n\n℣ Pray for us, O holy Mother of God.\n℟ That we may be made worthy of the promises of Christ. Amen.","la":"Salve, Regina, Mater misericordiae; vita, dulcedo, et spes nostra, salve. Ad te clamamus, exsules filii Evae; ad te suspiramus gementes et flentes in hac lacrimarum valle. Eia ergo, advocata nostra, illos tuos misericordes oculos ad nos converte; et Iesum, benedictum fructum ventris tui, nobis post hoc exsilium ostende. O clemens, o pia, o dulcis Virgo Maria.\n\n℣. Ora pro nobis, sancta Dei Genetrix.\n℟. Ut digni efficiamur promissionibus Christi.","fr":"Salut, Reine, mère de miséricorde, notre vie, notre douceur et notre espérance, salut! Vers vous nous crions, pauvres enfants d’Ève exilés; vers vous nous soupirons, gémissant et pleurant dans cette vallée de larmes. Ô vous, notre avocate, tournez vers nous vos regards miséricordieux; et après cet exil, montrez-nous Jésus, le fruit béni de vos entrailles, ô clémente, ô pieuse, ô douce Vierge Marie.\n\n℣. Priez pour nous, sainte Mère de Dieu.\n℟. Afin que nous devenions dignes des promesses du Christ.","source":"","sourceUrl":"","note":"","category":"marian","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Hail Holy Queen","witness":"Compendium of the Catechism of the Catholic Church · Appendix A","url":"https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_en.html","quality":"VERIFIED_PRIMARY","visibility":0,"adaptation":"VERBATIM","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_PRIMARY"},"note":"Common prayer; provenance retained internally and not shown by default."},"sourceAuditVersion":"35.7"},"marian_memorare":{"id":"marian_memorare","title":"Memorare (to Mary)","titleFr":"Souvenez-vous","en":"Remember, O most gracious Virgin Mary, that never was it known that anyone who fled to thy protection, implored thy help, or sought thy intercession was left unaided. Inspired by this confidence, I fly unto thee, O Virgin of virgins, my Mother; to thee do I come, before thee I stand, sinful and sorrowful. O Mother of the Word Incarnate, despise not my petitions, but in thy mercy hear and answer me. Amen.","la":"Memorare, o piissima Virgo Maria, non esse auditum a saeculo quemquam ad tua currentem praesidia, tua implorantem auxilia, tua petentem suffragia, esse derelictum. Ego, tali animatus confidentia, ad te, Virgo virginum, Mater, curro; ad te venio; coram te gemens peccator assisto. Noli, Mater Verbi, verba mea despicere; sed audi propitia et exaudi. Amen.","fr":"Souvenez-vous, ô très miséricordieuse Vierge Marie, qu’on n’a jamais entendu dire qu’aucun de ceux qui ont eu recours à votre protection, imploré votre secours, réclamé votre intercession, ait été abandonné. Animé d’une pareille confiance, ô Vierge des vierges, ô ma Mère, je cours vers vous, je viens à vous, et, gémissant sous le poids de mes péchés, je me prosterne à vos pieds. Ô Mère du Verbe incarné, ne méprisez pas mes prières, mais écoutez-les favorablement et daignez les exaucer. Amen.","source":"","sourceUrl":"","note":"","category":"marian","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Memorare","witness":"Compendium of the Catechism of the Catholic Church · Appendix A","url":"https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_en.html","quality":"VERIFIED_PRIMARY","visibility":0,"adaptation":"VERBATIM","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_PRIMARY"},"note":"Common prayer; provenance retained internally and not shown by default."},"sourceAuditVersion":"35.7"},"weekday_magnificat":{"id":"weekday_magnificat","title":"Magnificat (Mary)","titleFr":"Magnificat","en":"My soul proclaims the greatness of the Lord, my spirit rejoices in God my Savior for he has looked with favor on his lowly servant. From this day all generations will call me blessed: the Almighty has done great things for me, and holy is his Name.\n\nHe has mercy on those who fear him in every generation. He has shown the strength of his arm, he has scattered the proud in their conceit. He has cast down the mighty from their thrones, and has lifted up the lowly. He has filled the hungry with good things, and the rich he has sent away empty.\n\nHe has come to the help of his servant Israel for he has remembered his promise of mercy, the promise he made to our fathers, to Abraham and his children forever.\n\nGlory to the Father, and to the Son, and to the Holy Spirit: as it was in the beginning, is now, and will be forever. Amen.","la":"Magnificat anima mea Dominum, et exsultavit spiritus meus in Deo salutari meo; quia respexit humilitatem ancillae suae. Ecce enim ex hoc beatam me dicent omnes generationes, quia fecit mihi magna qui potens est, et sanctum nomen eius, et misericordia eius a progenie in progenies timentibus eum. Fecit potentiam in brachio suo, dispersit superbos mente cordis sui; deposuit potentes de sede, et exaltavit humiles; esurientes implevit bonis, et divites dimisit inanes. Suscepit Israel puerum suum, recordatus misericordiae, sicut locutus est ad patres nostros, Abraham et semini eius in saecula.","fr":"Mon âme exalte le Seigneur, exulte mon esprit en Dieu, mon Sauveur! Il s’est penché sur son humble servante; désormais tous les âges me diront bienheureuse. Le Puissant fit pour moi des merveilles; saint est son nom! Sa miséricorde s’étend d’âge en âge sur ceux qui le craignent. Déployant la force de son bras, il disperse les superbes. Il renverse les puissants de leurs trônes, il élève les humbles. Il comble de biens les affamés, renvoie les riches les mains vides. Il relève Israël, son serviteur, il se souvient de son amour, de la promesse faite à nos pères, en faveur d’Abraham et de sa descendance, à jamais.","source":"","sourceUrl":"","note":"","category":"marian","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Magnificat","witness":"Compendium of the Catechism of the Catholic Church · Appendix A","url":"https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_en.html","quality":"VERIFIED_PRIMARY","visibility":0,"adaptation":"VERBATIM","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_PRIMARY"},"note":"Common prayer; provenance retained internally and not shown by default."},"sourceAuditVersion":"35.7"},"marian_consecration_immaculate_heart":{"id":"marian_consecration_immaculate_heart","title":"Consecration to Immaculate Heart","titleFr":"Consécration au Cœur Immaculé","en":"O Immaculate Heart of Mary, Queen of Heaven and Earth, and tender Mother of men, in accordance with Thy ardent wish made known at Fatima, I consecrate to Thy Immaculate Heart myself, my brethren, my country, and the whole human race.\n\nReign over us, Most Holy Mother of God, and teach us how to make the Heart of Thy Son, Our Lord Jesus Christ reign and triumph in us even as It has reigned and triumphed in Thee.\n\nReign over us, Most Blessed Virgin, that we may be Thine in prosperity and in adversity, in joy and in sorrow, in health and in sickness, in life and in death.\n\nO most compassionate Heart of Mary, Queen of Heaven, watch over our minds and hearts and preserve them from the impurity which Thou didst lament so sorrowfully at Fatima. Assist us in imitating Thee in all things, especially purity. Help us to call down upon our country and upon the whole world the peace of God in justice and charity.\n\nTherefore, Most Gracious Virgin and Mother, I hereby promise to imitate Thy virtues by the practice of a true Christian life without regard to human respect.\n\nI resolve to receive Holy Communion regularly and to offer to Thee five decades of the Rosary each day, together with my sacrifices, in the spirit of reparation and penance. Amen.","la":"","fr":"","source":"Traditional Fatima consecration","sourceUrl":"https://fatima.org/act-of-cosnecration-to-the-immaculate-heart-of-mary/","note":"The exact historical English Fatima devotional form is retained. Latin and French remain deliberately withheld until exact witnesses of this same formula—not a different consecration text—are verified.","category":"marian","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":true,"sourceStatus":"VERIFIED_SECONDARY","provenance":{"work":"Act of Consecration to the Immaculate Heart of Mary","witness":"Historical Fatima devotional witness","url":"https://fatima.org/act-of-cosnecration-to-the-immaculate-heart-of-mary/","quality":"VERIFIED_SECONDARY","visibility":1,"adaptation":"VERBATIM","languages":{"en":"VERIFIED_SECONDARY","la":"SOURCE_PENDING","fr":"SOURCE_PENDING"},"note":"English exact witness retained. Latin and French remain deliberately pending because readily available Pius-XII/Fatima consecrations are different texts and must not be substituted merely to complete the language matrix."},"sourceAuditVersion":"41.4"},"adoration_anima_christi":{"id":"adoration_anima_christi","title":"Anima Christi","titleFr":"Anima Christi","en":"Soul of Christ, sanctify me. Body of Christ, save me. Blood of Christ, inebriate me. Water from the side of Christ, wash me. Passion of Christ, strengthen me. O good Jesus, hear me. Within your wounds hide me. Permit me not to be separated from you. From the wicked foe defend me. At the hour of my death call me and bid me come to you, that with your saints I may praise you forever and ever. Amen.","la":"Anima Christi, sanctifica me. Corpus Christi, salva me. Sanguis Christi, inebria me. Aqua lateris Christi, lava me. Passio Christi, conforta me. O bone Iesu, exaudi me. Intra tua vulnera absconde me. Ne permittas me separari a te. Ab hoste maligno defende me. In hora mortis meae voca me, et iube me venire ad te, ut cum Sanctis tuis laudem te in saecula saeculorum. Amen.","fr":"Âme du Christ, sanctifie-moi. Corps du Christ, sauve-moi. Sang du Christ, enivre-moi. Eau du côté du Christ, lave-moi. Passion du Christ, fortifie-moi. Ô bon Jésus, exauce-moi. Dans tes plaies, cache-moi. Ne permets pas que je sois séparé de toi. De l’ennemi perfide, défends-moi. À l’heure de ma mort, appelle-moi; ordonne-moi de venir à toi, pour qu’avec tes saints je te loue dans les siècles des siècles. Amen.","source":"","sourceUrl":"","note":"","category":"eucharistic","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Anima Christi","witness":"Vatican Compendium (Latin); traditional English/French witnesses","url":"https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_en.html","quality":"VERIFIED_PRIMARY","visibility":0,"adaptation":"TRADITIONAL_TRANSLATION","languages":{"en":"VERIFIED_SECONDARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_SECONDARY"},"note":"The common prayer is traceable internally; no visible source line is needed."},"sourceAuditVersion":"35.7"},"adoration_spiritual_communion":{"id":"adoration_spiritual_communion","title":"Spiritual Communion","titleFr":"Communion spirituelle","en":"My Jesus, I believe that You are present in the Most Blessed Sacrament. I love You above all things, and I desire to receive You into my soul. Since I cannot now receive You sacramentally, come at least spiritually into my heart. I embrace You as if You were already there, and I unite myself wholly to You. Never permit me to be separated from You.","la":"Iesu mi, credo te in Sanctissimo Sacramento praesente; te amo super omnia et desidero te in animam meam recipere. Quoniam nunc non possum te sacramentaliter recipere, veni saltem spiritualiter in cor meum. Te amplexus sum, ac me totum tibi unio; ne permittas me umquam separari a te. Amen.","fr":"Mon Jésus, je crois que tu es réellement présent dans le Très Saint Sacrement. Je t’aime par-dessus tout et je désire te recevoir dans mon âme. Comme je ne peux pas maintenant te recevoir sacramentellement, viens au moins spirituellement dans mon cœur. Comme si tu y étais déjà venu, je t’adore et je m’unis entièrement à toi. Ne permets pas que je sois jamais séparé de toi. Amen.","source":"St Alphonsus Liguori","sourceUrl":"https://www.vaticannews.va/en/prayers/the-spiritual-communion.html","note":"","category":"eucharistic","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":true,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Act of Spiritual Communion","witness":"Vatican News · attributed to St Alphonsus Liguori","url":"https://www.vaticannews.va/en/prayers/the-spiritual-communion.html","quality":"VERIFIED_PRIMARY","visibility":1,"adaptation":"VERBATIM","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_SECONDARY","fr":"VERIFIED_SECONDARY"},"note":""},"sourceAuditVersion":"35.7"},"benediction_o_salutaris":{"id":"benediction_o_salutaris","title":"O Salutaris Hostia","titleFr":"O Salutaris Hostia","en":"O saving Victim, open wide the gate of heaven to us below; our foes press on from every side, your aid supply, your strength bestow.\n\nTo your great name be endless praise, immortal Godhead, One in Three; O grant us endless length of days, in our true native land with thee. Amen.","la":"O salutaris Hostia,\nQuae caeli pandis ostium:\nBella premunt hostilia,\nDa robur, fer auxilium.\nUni trinoque Domino\nSit sempiterna gloria,\nQui vitam sine termino\nNobis donet in patria. Amen.","fr":"Ô Victime sainte, qui ouvrez\nLa porte du ciel à nous ici-bas,\nLes ennemis nous pressent de tous côtés,\nDonnez force, apportez secours.\nAu Seigneur unique et trinitaire\nSoit la gloire éternelle,\nQu’Il nous donne la vie sans fin\nDans notre patrie véritable. Amen.","source":"St Thomas Aquinas","sourceUrl":"https://en.wikisource.org/wiki/With_God/Benediction_of_the_Blessed_Sacrament","note":"","category":"eucharistic","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":true,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"O Salutaris Hostia","witness":"Lasance · With God · Benediction of the Blessed Sacrament","url":"https://en.wikisource.org/wiki/With_God/Benediction_of_the_Blessed_Sacrament","quality":"VERIFIED_PRIMARY","visibility":1,"adaptation":"TRADITIONAL_TRANSLATION","languages":{"en":"VERIFIED_SECONDARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_SECONDARY"},"note":"Latin hymn text is traditional; translations are tracked separately."},"sourceAuditVersion":"35.7"},"benediction_tantum_ergo":{"id":"benediction_tantum_ergo","title":"Tantum Ergo","titleFr":"Tantum Ergo","en":"Down in adoration falling, Lo! the sacred Host we hail; Lo! o’er ancient forms departing, newer rites of grace prevail; faith for all defects supplying, where the feeble senses fail.\n\nTo the everlasting Father, and the Son who reigns on high, with the Holy Spirit proceeding forth from each eternally, be salvation, honor, blessing, might and endless majesty. Amen.","la":"Tantum ergo Sacramentum\nVeneremur cernui:\nEt antiquum documentum\nNovo cedat ritui:\nPraestet fides supplementum\nSensuum defectui.\n\nGenitori, Genitoque\nLaus et jubilatio,\nSalus, honor, virtus quoque\nSit et benedictio:\nProcedenti ab utroque\nCompar sit laudatio. Amen.","fr":"Devant un si grand Sacrement,\nProsternons-nous en adoration;\nQue l’ancien rite cède la place\nAu nouveau rite de grâce;\nQue la foi supplée à la faiblesse\nDe nos sens défaillants.\n\nAu Père et au Fils,\nLouange et jubilation,\nSalut, honneur, puissance aussi\nEt bénédiction;\nÀ Celui qui procède des deux\nSoit semblable louange. Amen.","source":"St Thomas Aquinas","sourceUrl":"https://en.wikisource.org/wiki/With_God/Benediction_of_the_Blessed_Sacrament","note":"","category":"eucharistic","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":true,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Tantum Ergo","witness":"Lasance · With God · Benediction of the Blessed Sacrament","url":"https://en.wikisource.org/wiki/With_God/Benediction_of_the_Blessed_Sacrament","quality":"VERIFIED_PRIMARY","visibility":1,"adaptation":"TRADITIONAL_TRANSLATION","languages":{"en":"VERIFIED_SECONDARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_SECONDARY"},"note":"Latin hymn text is traditional; translations are tracked separately."},"sourceAuditVersion":"35.7"},"benediction_divine_praises":{"id":"benediction_divine_praises","title":"Divine Praises","titleFr":"Louanges divines","en":"Blessed be God.\nBlessed be His Holy Name.\nBlessed be Jesus Christ, true God and true man.\nBlessed be the Name of Jesus.\nBlessed be His most Sacred Heart.\nBlessed be His most Precious Blood.\nBlessed be Jesus in the most Holy Sacrament of the Altar.\nBlessed be the Holy Spirit, the Paraclete.\nBlessed be the great Mother of God, Mary most holy.\nBlessed be her holy and Immaculate Conception.\nBlessed be her glorious Assumption.\nBlessed be the name of Mary, Virgin and Mother.\nBlessed be Saint Joseph, her most chaste spouse.\nBlessed be God in His Angels and in His Saints.","la":"Benedictus Deus.\nBenedictum Nomen Sanctum eius.\nBenedictus Iesus Christus, verus Deus et verus homo.\nBenedictum Nomen Iesu.\nBenedictum Cor eius sacratissimum.\nBenedictus Sanguis eius pretiosissimus.\nBenedictus Iesus in sanctissimo altaris Sacramento.\nBenedictus Spiritus Sanctus, Paraclitus.\nBenedicta magna Mater Dei, Maria sanctissima.\nBenedicta sancta eius et immaculata Conceptio.\nBenedicta gloriosa eius Assumptio.\nBenedictum nomen Mariae, Virginis et Matris.\nBenedictus sanctus Ioseph, eius castissimus Sponsus.\nBenedictus Deus in angelis suis et in sanctis suis.","fr":"Béni soit Dieu.\nBéni soit son saint Nom.\nBéni soit Jésus-Christ, vrai Dieu et vrai homme.\nBéni soit le Nom de Jésus.\nBéni soit son Sacré-Cœur.\nBéni soit son Précieux Sang.\nBéni soit Jésus dans le très saint Sacrement de l’autel.\nBéni soit l’Esprit Saint, le Paraclet.\nBénie soit la grande Mère de Dieu, Marie très sainte.\nBénie soit sa sainte et immaculée Conception.\nBénie soit sa glorieuse Assomption.\nBéni soit le nom de Marie, Vierge et Mère.\nBéni soit saint Joseph, son très chaste époux.\nBéni soit Dieu dans ses anges et dans ses saints.","source":"Eucharistic Worship outside Mass · no. 99","sourceUrl":"https://www.usccb.org/prayers/divine-praises","note":"","category":"eucharistic","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":true,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"The Divine Praises","witness":"Holy Communion and Worship of the Eucharistic Mystery outside Mass · no. 99","url":"https://www.usccb.org/prayers/divine-praises","quality":"VERIFIED_PRIMARY","visibility":1,"adaptation":"VERBATIM","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_SECONDARY","fr":"VERIFIED_SECONDARY"},"note":""},"sourceAuditVersion":"35.7"},"adoration_litany_blessed_sacrament":{"id":"adoration_litany_blessed_sacrament","title":"Litany of the Most Blessed Sacrament","titleFr":"Litanies du Très Saint Sacrement","en":"Lord, have mercy on us. Christ, have mercy on us. Lord, have mercy on us.\nChrist, hear us. Christ, graciously hear us.\nGod the Father of heaven, have mercy on us.\nGod the Son, Redeemer of the world, have mercy on us.\nGod the Holy Spirit, have mercy on us.\nHoly Trinity, one God, have mercy on us.\n\nLiving Bread which came down from heaven, have mercy on us.\nHidden God and Saviour, have mercy on us.\nWheat of the elect, have mercy on us.\nWine springing forth virgins, have mercy on us.\nBread of delight for kings, have mercy on us.\nPerpetual sacrifice, have mercy on us.\nPure oblation, have mercy on us.\nLamb without spot, have mercy on us.\nTable of holiness, have mercy on us.\nFood of Angels, have mercy on us.\nManna of inward strength, have mercy on us.\nMemorial of the wonders of God, have mercy on us.\nWord made flesh, dwelling among us, have mercy on us.\nSacred and adorable Host, have mercy on us.\nChalice of blessing, have mercy on us.\nMystery of faith, have mercy on us.\nMost high and venerable Sacrament, have mercy on us.\nMost holy sacrifice, have mercy on us.\nSacrifice of propitiation for the living and the dead, have mercy on us.\nHeavenly remedy against sin, have mercy on us.\nMemorial of the Passion of the Lord, have mercy on us.\nMost precious gift, have mercy on us.\nTenderest pledge of divine love, have mercy on us.\nPledge of our future glory, have mercy on us.\nSacrament of love, have mercy on us.\nBond of charity, have mercy on us.\nRefreshment of holy souls, have mercy on us.\nViaticum of those who die in the Lord, have mercy on us.\n\nFrom receiving your adorable Body and Blood unworthily, deliver us, O Lord.\nFrom the concupiscence of the flesh, deliver us, O Lord.\nFrom the concupiscence of the eyes, deliver us, O Lord.\nFrom the pride of life, deliver us, O Lord.\nFrom every occasion of sin, deliver us, O Lord.\n\nWe sinners, beseech you, hear us.\nThat you would increase and preserve in us faith, reverence and devotion toward this admirable Sacrament, we beseech you, hear us.\nThat through humble and sincere confession you would lead us to frequent reception of the Holy Eucharist, we beseech you, hear us.\nThat you would preserve us from heresy, unbelief and blindness of heart, we beseech you, hear us.\nThat you would grant us the heavenly fruits of this most holy Sacrament, we beseech you, hear us.\nThat at the hour of death you would strengthen us with this heavenly Viaticum, we beseech you, hear us.\n\nLamb of God, who takes away the sins of the world, spare us, O Lord.\nLamb of God, who takes away the sins of the world, graciously hear us, O Lord.\nLamb of God, who takes away the sins of the world, have mercy on us.\n\n℣. You gave them Bread from heaven.\n℟. Containing in itself all delight.\n\nLet us pray. O God, who in this wonderful Sacrament have left us a memorial of your Passion, grant us, we beseech you, so to venerate the sacred mysteries of your Body and Blood that we may ever experience within us the fruit of your redemption. Who live and reign forever and ever. Amen.","la":"Kyrie, eleison. Christe, eleison. Kyrie, eleison.\nChriste, audi nos. Christe, exaudi nos.\nPater de cælis, Deus, miserere nobis.\nFili, Redemptor mundi, Deus, miserere nobis.\nSpiritus Sancte, Deus, miserere nobis.\nSancta Trinitas, unus Deus, miserere nobis.\n\nPanis vivus, qui de cælo descendisti, miserere nobis.\nDeus absconditus et Salvator, miserere nobis.\nFrumentum electorum, miserere nobis.\nVinum germinans virgines, miserere nobis.\nPanis pinguis et deliciæ regum, miserere nobis.\nIuge sacrificium, miserere nobis.\nOblatio munda, miserere nobis.\nAgnus absque macula, miserere nobis.\nMensa purissima, miserere nobis.\nCibus Angelorum, miserere nobis.\nManna absconditum, miserere nobis.\nMemoriale mirabilium Dei, miserere nobis.\nVerbum caro factum, habitans in nobis, miserere nobis.\nHostia sancta et adoranda, miserere nobis.\nCalix benedictionis, miserere nobis.\nMysterium fidei, miserere nobis.\nPræcelsum et venerabile Sacramentum, miserere nobis.\nSacrificium sanctissimum, miserere nobis.\nSacrificium propitiatorium pro vivis et defunctis, miserere nobis.\nCæleste antidotum contra peccata, miserere nobis.\nMemoriale Passionis Dominicæ, miserere nobis.\nDonum super omnia dona, miserere nobis.\nPignus caritatis divinæ, miserere nobis.\nPignus futuræ gloriæ, miserere nobis.\nSacramentum dilectionis, miserere nobis.\nVinculum caritatis, miserere nobis.\nRefectio animarum sanctarum, miserere nobis.\nViaticum in Domino morientium, miserere nobis.\n\nA sumptione Corporis et Sanguinis tui indigna, libera nos, Domine.\nA concupiscentia carnis, libera nos, Domine.\nA concupiscentia oculorum, libera nos, Domine.\nA superbia vitæ, libera nos, Domine.\nAb omni occasione peccandi, libera nos, Domine.\n\nPeccatores, te rogamus, audi nos.\nUt fidem, reverentiam et devotionem erga hoc admirabile Sacramentum augere et conservare digneris, te rogamus, audi nos.\nUt ad frequentem sanctæ Eucharistiæ susceptionem per humilem et sinceram confessionem nos perducere digneris, te rogamus, audi nos.\nUt nos ab omni hæresi, infidelitate et cordis cæcitate liberare digneris, te rogamus, audi nos.\nUt fructus pretiosos huius sanctissimi Sacramenti nobis impertiri digneris, te rogamus, audi nos.\nUt in hora mortis cælesti hoc Viatico nos confortare digneris, te rogamus, audi nos.\n\nAgnus Dei, qui tollis peccata mundi, parce nobis, Domine.\nAgnus Dei, qui tollis peccata mundi, exaudi nos, Domine.\nAgnus Dei, qui tollis peccata mundi, miserere nobis.\n\n℣. Panem de cælo præstitisti eis.\n℟. Omne delectamentum in se habentem.\n\nOremus. Deus, qui nobis sub Sacramento mirabili Passionis tuæ memoriam reliquisti: tribue, quæsumus, ita nos Corporis et Sanguinis tui sacra mysteria venerari, ut redemptionis tuæ fructum in nobis iugiter sentiamus. Qui vivis et regnas in sæcula sæculorum. Amen.","fr":"Seigneur, ayez pitié de nous. Jésus-Christ, ayez pitié de nous. Seigneur, ayez pitié de nous.\nJésus-Christ, écoutez-nous. Jésus-Christ, exaucez-nous.\nPère céleste, qui êtes Dieu, ayez pitié de nous.\nFils, Rédempteur du monde, qui êtes Dieu, ayez pitié de nous.\nEsprit-Saint, qui êtes Dieu, ayez pitié de nous.\nTrinité Sainte, qui êtes un seul Dieu, ayez pitié de nous.\n\nPain vivant descendu du ciel, ayez pitié de nous.\nDieu caché et Sauveur, ayez pitié de nous.\nFroment des élus, ayez pitié de nous.\nVin qui faites germer les vierges, ayez pitié de nous.\nPain délicieux des rois, ayez pitié de nous.\nSacrifice perpétuel, ayez pitié de nous.\nOblation pure, ayez pitié de nous.\nAgneau sans tache, ayez pitié de nous.\nTable de sainteté, ayez pitié de nous.\nNourriture des Anges, ayez pitié de nous.\nManne cachée, ayez pitié de nous.\nMémorial des merveilles de Dieu, ayez pitié de nous.\nVerbe fait chair, habitant parmi nous, ayez pitié de nous.\nHostie sainte et adorable, ayez pitié de nous.\nCalice de bénédiction, ayez pitié de nous.\nMystère de foi, ayez pitié de nous.\nSacrement très haut et très vénérable, ayez pitié de nous.\nSacrifice très saint, ayez pitié de nous.\nSacrifice de propitiation pour les vivants et les morts, ayez pitié de nous.\nRemède céleste contre le péché, ayez pitié de nous.\nMémorial de la Passion du Seigneur, ayez pitié de nous.\nDon très précieux, ayez pitié de nous.\nGage très tendre de l’amour divin, ayez pitié de nous.\nGage de notre gloire future, ayez pitié de nous.\nSacrement d’amour, ayez pitié de nous.\nLien de charité, ayez pitié de nous.\nRafraîchissement des âmes saintes, ayez pitié de nous.\nViatique de ceux qui meurent dans le Seigneur, ayez pitié de nous.\n\nDe la réception indigne de votre Corps et de votre Sang adorables, délivrez-nous, Seigneur.\nDe la concupiscence de la chair, délivrez-nous, Seigneur.\nDe la concupiscence des yeux, délivrez-nous, Seigneur.\nDe l’orgueil de la vie, délivrez-nous, Seigneur.\nDe toute occasion de péché, délivrez-nous, Seigneur.\n\nPécheurs que nous sommes, nous vous en prions, écoutez-nous.\nDaignez accroître et conserver en nous la foi, le respect et la dévotion envers cet admirable Sacrement, nous vous en prions, écoutez-nous.\nDaignez nous conduire, par une confession humble et sincère, à la réception fréquente de la sainte Eucharistie, nous vous en prions, écoutez-nous.\nDaignez nous préserver de l’hérésie, de l’incrédulité et de l’aveuglement du cœur, nous vous en prions, écoutez-nous.\nDaignez nous accorder les fruits célestes de ce très saint Sacrement, nous vous en prions, écoutez-nous.\nÀ l’heure de notre mort, daignez nous fortifier par ce céleste Viatique, nous vous en prions, écoutez-nous.\n\nAgneau de Dieu, qui effacez les péchés du monde, pardonnez-nous, Seigneur.\nAgneau de Dieu, qui effacez les péchés du monde, exaucez-nous, Seigneur.\nAgneau de Dieu, qui effacez les péchés du monde, ayez pitié de nous.\n\n℣. Vous leur avez donné un pain venu du ciel.\n℟. Qui renferme en lui toutes les délices.\n\nPrions. Ô Dieu, qui nous avez laissé dans cet admirable Sacrement le mémorial de votre Passion, accordez-nous, nous vous en supplions, de vénérer les saints mystères de votre Corps et de votre Sang de telle sorte que nous ressentions toujours en nous le fruit de votre rédemption. Vous qui vivez et régnez dans les siècles des siècles. Ainsi soit-il.","source":"Lasance · With God · 1911","sourceUrl":"https://en.wikisource.org/wiki/With_God/Litanies","note":"","category":"eucharistic","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":true,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Litany of the Blessed Sacrament","witness":"F. X. Lasance · With God · 1911 · p. 496","url":"https://en.wikisource.org/wiki/With_God/Litanies","quality":"VERIFIED_PRIMARY","visibility":1,"adaptation":"TYPOGRAPHY_NORMALIZED","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_SECONDARY","fr":"VERIFIED_SECONDARY"},"note":"Historical indulgence notices are not presented as current grants."},"sourceAuditVersion":"35.7"},"benediction_versicles":{"id":"benediction_versicles","title":"Versicle & Prayer (English)","titleFr":"Versets et oraison de la bénédiction","en":"℣. You have given them Bread from Heaven.\n℟. Having within it all sweetness.\n\nLet us pray:\nO God, who in this wonderful Sacrament left us a memorial of your Passion:\ngrant us, we beseech you, so to venerate the sacred mysteries of your Body and Blood,\nthat we may ever feel within us the fruit of your redemption.\nWho live and reign forever and ever. Amen.","la":"V. Panem de caelo praestitisti eis.\nR. Omne delectamentum in se habentem.\n\nOremus:\nDeus, qui nobis sub sacramento mirabili passionis tuae memoriam reliquisti:\ntribue, quaesumus, ita nos Corporis et Sanguinis tui sacra mysteria venerari,\nut redemptionis tuae fructum in nobis iugiter sentiamus.\nQui vivis et regnas in saecula saeculorum. Amen.","fr":"V. Vous leur avez donné le Pain du ciel.\nR. Qui contient en lui toutes délices.\n\nPrions :\nÔ Dieu, qui dans ce merveilleux Sacrement nous avez laissé le mémorial de votre Passion :\naccordez-nous de vénérer les saints mystères de votre Corps et de votre Sang,\nafin que nous ressentions toujours en nous le fruit de la rédemption.\nPar le Christ notre Seigneur. Amen.","source":"Traditional Benediction","sourceUrl":"https://en.wikisource.org/wiki/With_God/Benediction_of_the_Blessed_Sacrament","note":"","category":"eucharistic","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":true,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Panem de caelo / Deus qui nobis","witness":"Lasance · With God · Benediction of the Blessed Sacrament","url":"https://en.wikisource.org/wiki/With_God/Benediction_of_the_Blessed_Sacrament","quality":"VERIFIED_PRIMARY","visibility":1,"adaptation":"TRADITIONAL_TRANSLATION","languages":{"en":"VERIFIED_SECONDARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_SECONDARY"},"note":""},"sourceAuditVersion":"35.7"},"adoration_lord_i_am_not_worthy":{"id":"adoration_lord_i_am_not_worthy","title":"Lord, I Am Not Worthy","titleFr":"Domine, non sum dignus","en":"Lord, I am not worthy that Thou shouldst enter under my roof; but only say the word and my soul shall be healed.","la":"Domine, non sum dignus ut intres sub tectum meum; sed tantum dic verbo, et sanabitur anima mea.","fr":"Seigneur, je ne suis pas digne que vous entriez sous mon toit ; mais dites seulement une parole et mon âme sera guérie.","source":"Missale Romanum 1962 · Communion formula","sourceUrl":"","note":"Traditional English/French rendering of the Latin formula.","category":"massdev"},"mass_devotion_leonine":{"id":"mass_devotion_leonine","title":"Leonine Prayers After Low Mass","titleFr":"Prières léonines après la Messe basse","en":"Hail Mary, full of grace, the Lord is with thee; blessed art thou among women, and blessed is the fruit of thy womb, Jesus. Holy Mary, Mother of God, pray for us sinners, now and at the hour of our death. Amen. (three times)\n----\nHail, holy Queen, Mother of mercy, our life, our sweetness and our hope. To thee do we cry, poor banished children of Eve; to thee do we send up our sighs, mourning and weeping in this vale of tears. Turn then, most gracious advocate, thine eyes of mercy toward us; and after this our exile show unto us the blessed fruit of thy womb, Jesus. O clement, O loving, O sweet Virgin Mary.\n\n℣. Pray for us, O holy Mother of God.\n℟. That we may be made worthy of the promises of Christ.\n----\nLet us pray. O God, our refuge and our strength, look down in mercy on your people who cry to you; and by the intercession of the glorious and immaculate Virgin Mary, Mother of God, of Saint Joseph her spouse, of your blessed Apostles Peter and Paul, and of all the Saints, mercifully and graciously hear the prayers which we pour forth for the conversion of sinners and for the freedom and exaltation of Holy Mother Church. Through the same Christ our Lord. Amen.\n----\nSaint Michael the Archangel, defend us in battle; be our protection against the wickedness and snares of the devil. May God rebuke him, we humbly pray; and do thou, O Prince of the heavenly host, by the power of God, cast into hell Satan and all the evil spirits who prowl throughout the world seeking the ruin of souls. Amen.\n----\nMost Sacred Heart of Jesus, have mercy on us. (three times)","la":"Ave Maria, gratia plena, Dominus tecum; benedicta tu in mulieribus, et benedictus fructus ventris tui, Iesus. Sancta Maria, Mater Dei, ora pro nobis peccatoribus, nunc et in hora mortis nostræ. Amen. (ter)\n----\nSalve, Regina, Mater misericordiæ; vita, dulcedo et spes nostra, salve. Ad te clamamus, exsules filii Hevæ. Ad te suspiramus, gementes et flentes in hac lacrimarum valle. Eia ergo, advocata nostra, illos tuos misericordes oculos ad nos converte. Et Iesum, benedictum fructum ventris tui, nobis post hoc exsilium ostende. O clemens, o pia, o dulcis Virgo Maria.\n\n℣. Ora pro nobis, sancta Dei Genetrix.\n℟. Ut digni efficiamur promissionibus Christi.\n----\nOremus. Deus, refugium nostrum et virtus, populum ad te clamantem propitius respice; et intercedente gloriosa et immaculata Virgine Dei Genetrice Maria, cum beato Ioseph, eius Sponso, ac beatis Apostolis tuis Petro et Paulo, et omnibus Sanctis, quas pro conversione peccatorum, pro libertate et exaltatione sanctæ Matris Ecclesiæ, preces effundimus, misericors et benignus exaudi. Per eundem Christum Dominum nostrum. Amen.\n----\nSancte Michael Archangele, defende nos in prœlio; contra nequitiam et insidias diaboli esto præsidium. Imperet illi Deus, supplices deprecamur: tuque, Princeps militiæ cælestis, Satanam aliosque spiritus malignos, qui ad perditionem animarum pervagantur in mundo, divina virtute in infernum detrude. Amen.\n----\nCor Iesu sacratissimum, miserere nobis. (ter)","fr":"Je vous salue, Marie, pleine de grâce; le Seigneur est avec vous; vous êtes bénie entre toutes les femmes, et Jésus, le fruit de vos entrailles, est béni. Sainte Marie, Mère de Dieu, priez pour nous, pauvres pécheurs, maintenant et à l’heure de notre mort. Ainsi soit-il. (trois fois)\n----\nSalut, ô Reine, Mère de miséricorde, notre vie, notre douceur et notre espérance, salut. Enfants d’Ève exilés, nous crions vers vous. Vers vous nous soupirons, gémissant et pleurant dans cette vallée de larmes. Ô vous, notre avocate, tournez vers nous vos regards miséricordieux. Et après cet exil, montrez-nous Jésus, le fruit béni de vos entrailles. Ô clémente, ô charitable, ô douce Vierge Marie.\n\n℣. Priez pour nous, Sainte Mère de Dieu.\n℟. Afin que nous devenions dignes des promesses de Jésus-Christ.\n----\nPrions. Ô Dieu, notre refuge et notre force, regardez favorablement le peuple qui crie vers vous; et par l’intercession de la glorieuse et immaculée Vierge Marie, Mère de Dieu, de saint Joseph son époux, de vos bienheureux Apôtres Pierre et Paul et de tous les saints, écoutez avec miséricorde et bonté les prières que nous répandons pour la conversion des pécheurs, pour la liberté et l’exaltation de notre sainte Mère l’Église. Par le même Jésus-Christ Notre-Seigneur. Ainsi soit-il.\n----\nSaint Michel Archange, défendez-nous dans le combat; soyez notre secours contre la malice et les embûches du démon. Que Dieu lui commande, nous vous en supplions; et vous, Prince de la milice céleste, par la puissance divine, repoussez en enfer Satan et les autres esprits mauvais qui rôdent dans le monde pour la perte des âmes. Ainsi soit-il.\n----\nCœur Sacré de Jésus, ayez pitié de nous. (trois fois)","source":"Prayers after Low Mass · historical Leonine form","sourceUrl":"https://en.wikisource.org/wiki/The_Catholic%27s_pocket_prayer-book/Prayers_after_Low-Mass","note":"Historically prescribed after Low Mass; retained here as a traditional post-Mass devotion.","category":"massdev","sourceStatus":"VERIFIED_SECONDARY","provenance":{"work":"Prayers after Low Mass (Leonine Prayers)","witness":"The Catholic's Pocket Prayer-Book · Prayers after Low-Mass","url":"https://en.wikisource.org/wiki/The_Catholic%27s_pocket_prayer-book/Prayers_after_Low-Mass","quality":"VERIFIED_SECONDARY","visibility":1,"adaptation":"TYPOGRAPHY_NORMALIZED","languages":{"en":"VERIFIED_SECONDARY","la":"VERIFIED_SECONDARY","fr":"VERIFIED_SECONDARY"},"note":"The historical prayer-book witness supplies the sequence; no claim is made that this devotion forms part of the Mass itself."}},"sacrament_come_holy_spirit":{"id":"sacrament_come_holy_spirit","title":"Come, Holy Spirit","titleFr":"Venez, Esprit-Saint","en":"Come, Holy Spirit, fill the hearts of your faithful and kindle in them the fire of your love. ℣. Send forth your Spirit and they shall be created.\n℟. And you shall renew the face of the earth.\n\nLet us pray. O God, who by the light of the Holy Spirit did instruct the hearts of the faithful, grant that by the same Holy Spirit we may be truly wise and ever enjoy his consolations. Through Christ our Lord. Amen.","la":"Veni, Sancte Spiritus, reple tuorum corda fidelium, et tui amoris in eis ignem accende. ℣. Emitte Spiritum tuum, et creabuntur.\n℟. Et renovabis faciem terrae. Oremus. Deus, qui corda fidelium Sancti Spiritus illustratione docuisti, da nobis in eodem Spiritu recta sapere, et de eius semper consolatione gaudere. Per Christum Dominum nostrum. Amen.","fr":"Viens, Esprit Saint, remplis le cœur de tes fidèles et allume en eux le feu de ton amour. ℣. Envoie ton Esprit, et tout sera créé.\n℟. Et tu renouvelleras la face de la terre. Prions. Dieu, qui as instruit le cœur de tes fidèles par la lumière du Saint-Esprit, donne-nous, par ce même Esprit, de goûter ce qui est bien et de jouir toujours de ses consolations. Par le Christ, notre Seigneur. Amen.","source":"","sourceUrl":"","note":"","category":"holyghost","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Prayer to the Holy Spirit","witness":"USCCB prayer witness","url":"https://www.usccb.org/prayers/prayer-holy-spirit","quality":"VERIFIED_PRIMARY","visibility":0,"adaptation":"TRADITIONAL_TRANSLATION","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_SECONDARY"},"note":""},"sourceAuditVersion":"35.7"},"weekday_benedictus":{"id":"weekday_benedictus","title":"Benedictus (Zechariah)","titleFr":"Benedictus","en":"Blessed be the Lord, the God of Israel; he has come to his people and set them free. He has raised up for us a mighty savior, born of the house of his servant David.\n\nThrough his holy prophets he promised of old that he would save us from our enemies, from the hands of all who hate us. He promised to show mercy to our fathers and to remember his holy covenant.\n\nThis was the oath he swore to our father Abraham: to set us free from the hands of our enemies, free to worship him without fear, holy and righteous in his sight all the days of our life.\n\nYou, my child, shall be called the prophet of the Most High; for you will go before the Lord to prepare his way, to give his people knowledge of salvation by the forgiveness of their sins.\n\nIn the tender compassion of our God the dawn from on high shall break upon us, to shine on those who dwell in darkness and the shadow of death, and to guide our feet into the way of peace.\n\nGlory to the Father, and to the Son, and to the Holy Spirit: as it was in the beginning, is now, and will be forever. Amen.","la":"Benedictus Dominus Deus Israel, quia visitavit et fecit redemptionem plebis suae, et erexit cornu salutis nobis in domo David pueri sui, sicut locutus est per os sanctorum, qui a saeculo sunt, prophetarum eius, salutem ex inimicis nostris, et de manu omnium qui oderunt nos; ad faciendam misericordiam cum patribus nostris et memorari testamenti sui sancti; iusjurandum quod iuravit ad Abraham patrem nostrum daturum se nobis, ut sine timore, de manu inimicorum nostrorum liberati, serviamus illi in sanctitate et iustitia coram ipso omnibus diebus nostris. Et tu, puer, propheta Altissimi vocaberis; praeibis enim ante faciem Domini parare vias eius, ad dandam scientiam salutis plebi eius in remissionem peccatorum eorum, per viscera misericordiae Dei nostri, in quibus visitavit nos Oriens ex alto; illuminare his qui in tenebris et in umbra mortis sedent, ad dirigendos pedes nostros in viam pacis.","fr":"Béni soit le Seigneur, le Dieu d’Israël, qui visite et rachète son peuple. Il a fait surgir la force qui nous sauve dans la maison de David, son serviteur, comme il l’avait dit par la bouche des saints, par ses prophètes, depuis les temps anciens: salut qui nous arrache à l’ennemi, à la main de tous nos oppresseurs, amour qu’il montre envers nos pères, mémoire de son alliance sainte, serment juré à notre père Abraham de nous rendre sans crainte, afin que, délivrés de la main des ennemis, nous le servions dans la justice et la sainteté, en sa présence, tout au long de nos jours. Et toi, petit enfant, tu seras appelé prophète du Très-Haut; tu marcheras devant, à la face du Seigneur, et tu prépareras ses chemins pour donner à son peuple de connaître le salut par la rémission de ses péchés, grâce à la tendresse, à l’amour de notre Dieu, quand nous visite l’Astre d’en haut, pour illuminer ceux qui habitent les ténèbres et l’ombre de la mort, pour conduire nos pas au chemin de la paix.","source":"","sourceUrl":"","note":"","category":"canticles","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Benedictus","witness":"Compendium of the Catechism of the Catholic Church · Appendix A","url":"https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_en.html","quality":"VERIFIED_PRIMARY","visibility":0,"adaptation":"VERBATIM","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_PRIMARY"},"note":"Common prayer; provenance retained internally and not shown by default."},"sourceAuditVersion":"35.7"},"devotion_prayer_st_michael":{"id":"devotion_prayer_st_michael","title":"Prayer to St. Michael","titleFr":"Prière à saint Michel","en":"St. Michael the Archangel, defend us in battle. Be our protection against the wickedness and snares of the devil. May God rebuke him, we humbly pray; and do thou, O Prince of the heavenly host, by the power of God, thrust into hell Satan and all the evil spirits who prowl about the world seeking the ruin of souls. Amen.","la":"Sancte Michael Archangele, defende nos in proelio; contra nequitiam et insidias diaboli esto praesidium. Imperet illi Deus, supplices deprecamur: tuque, Princeps militiae caelestis, Satanam aliosque spiritus malignos, qui ad perditionem animarum pervagantur in mundo, divina virtute in infernum detrude. Amen.","fr":"Saint Michel Archange, défendez-nous dans le combat; soyez notre secours contre la malice et les embûches du démon. Que Dieu lui commande, nous vous en supplions; et vous, Prince de la milice céleste, par la puissance divine, repoussez en enfer Satan et les autres esprits mauvais qui rôdent dans le monde pour la perte des âmes. Amen.","source":"Leo XIII","sourceUrl":"https://press.vatican.va/content/salastampa/en/bollettino/pubblico/2018/09/29/180929d.html","note":"","category":"saints","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":true,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Prayer to Saint Michael the Archangel","witness":"Holy See Press Office · prayer written by Leo XIII","url":"https://press.vatican.va/content/salastampa/en/bollettino/pubblico/2018/09/29/180929d.html","quality":"VERIFIED_PRIMARY","visibility":1,"adaptation":"TRADITIONAL_TRANSLATION","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_SECONDARY"},"note":""},"sourceAuditVersion":"35.7"},"devotion_memorare_st_joseph":{"id":"devotion_memorare_st_joseph","title":"Memorare to St. Joseph","titleFr":"Souvenez-vous à saint Joseph","en":"Remember, O most pure spouse of the Virgin Mary, my sweet protector St. Joseph, that no one ever had recourse to your protection or implored your aid without obtaining relief. Confiding therefore in your goodness, I come before you. Do not turn down my petitions, foster-father of the Redeemer, but graciously receive them. Amen.","la":"Memorare, o castissime Ioseph, quod numquam auditum sit quemquam ad tuam confugisse protectionem, tuum auxilium implorasse, tua patrocinia petiisse, et non esse exauditum. Confidens hac spe, ad te venio, o custos Redemptoris dulcissime; suscipe preces meas et benignus exaudi. Amen.","fr":"Souvenez-vous, ô très chaste époux de la Vierge Marie, ô bon protecteur, saint Joseph, qu’on n’a jamais entendu dire que personne ait eu recours à votre protection, imploré votre secours ou réclamé votre assistance sans en avoir été consolé. Plein de cette confiance, je me présente devant vous et je me recommande à vous. Ne rejetez pas ma prière, mais accueillez-la avec bonté et daignez l’exaucer. Amen.","source":"","sourceUrl":"","note":"","category":"saints","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_SECONDARY","provenance":{"work":"Memorare to Saint Joseph","witness":"Diocese of Sacramento traditional prayer witness","url":"https://www.scd.org/stjoseph/prayers","quality":"VERIFIED_SECONDARY","visibility":0,"adaptation":"TRADITIONAL_TRANSLATION","languages":{"en":"VERIFIED_SECONDARY","la":"VERIFIED_SECONDARY","fr":"VERIFIED_SECONDARY"},"note":"Common devotional prayer; visible attribution suppressed."},"sourceAuditVersion":"35.7"},"devotion_consecration_christ_king":{"id":"devotion_consecration_christ_king","title":"Consecration to Christ the King","titleFr":"Consécration au Christ-Roi","en":"O Jesus Christ, I acknowledge Thee as universal King. All that has been made, has been created for Thee. Exercise all Thy rights over me. I renew my baptismal vows, I renounce Satan, his pomps and his works: and I promise to live as a good Christian. And in particular do I pledge myself to labor, to the best of my ability, for the triumph of the rights of God and of Thy Church. Divine Heart of Jesus, to Thee do I offer my poor services, laboring that all hearts may acknowledge Thy Sacred kingship, and thus the reign of Thy peace may be established throughout the universe. Amen.","la":"Dómine Iesu Christe, te confíteor Regem universálem. Omnia, quæ facta sunt, pro te sunt creáta. Omnia iura tua exérce in me. Rénovo vota Baptísmi abrenúntians sátanæ eiúsque pompis et opéribus et promítto me victúrum ut bonum Christiánum. Ac potíssimum me óbligo operári quantum in me est, ut triúmphent Dei iura tuæque Ecclésiæ. Divínum Cor Iesu, óffero tibi actiónes meas ténues ad obtinéndum, ut corda ómnia agnóscant tuam sacram Regalitátem et ita tuæ pacis regnum stabiliátur in toto terrárum orbe. Amen.","fr":"Ô Christ Jésus, je Vous reconnais pour Roi Universel. Tout ce qui a été fait a été créé pour Vous. Exercez sur moi tous Vos droits. Je renouvelle mes promesses du Baptême en renonçant à Satan, à ses pompes et à ses œuvres, et je promets de vivre en bon Chrétien. Et tout particulièrement je m’engage à faire triompher selon mes moyens les droits de Dieu et de votre Église. Divin Cœur de Jésus, je Vous offre mes pauvres actions pour obtenir que tous les cœurs reconnaissent votre Royauté Sacrée et qu’ainsi le règne de votre Paix s’établisse dans l’univers entier. Ainsi soit-il.","source":"Prayer to Christ the Universal King · Pius XI era · 1923","sourceUrl":"https://app.itheca.org/biblioteca/Oraciones/DeumUnuTri.html","note":"The former 1903 attribution was removed. The Latin text is witnessed as Oratio ad Iesum Christum Regem; the French traditional witness is printed in the 2025 Notre-Dame de Chrétienté pilgrim book as a 1923 prayer of Pope Pius XI.","category":"saints","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":true,"sourceStatus":"VERIFIED_SECONDARY","provenance":{"work":"Oratio ad D. N. Iesum Christum Regem","witness":"Traditional Pius-XI-era Christ-the-King prayer · 1923","url":"https://app.itheca.org/biblioteca/Oraciones/DeumUnuTri.html","quality":"VERIFIED_SECONDARY","visibility":1,"adaptation":"VERBATIM","languages":{"en":"VERIFIED_SECONDARY","la":"VERIFIED_SECONDARY","fr":"VERIFIED_SECONDARY"},"note":"Latin witness: ITheca prayer library. French witness: Notre-Dame de Chrétienté, Livret des pèlerins 2025, which identifies it as a 1923 prayer of Pope Pius XI.","frenchWitnessUrl":"https://www.nd-chretiente.com/wordpress/wp-content/uploads/2025/05/Livret-du-pelerin-2025.pdf"},"sourceAuditVersion":"41.4"},"church_prayer_for_pope":{"id":"church_prayer_for_pope","title":"Prayer for the Pope","titleFr":"Prière pour le Pape","en":"℣. Let us pray for our Sovereign Pontiff N.\n℟. May the Lord preserve him and give him life, and make him blessed upon the earth, and deliver him not up to the will of his enemies.\n\n℣. Thou art Peter.\n℟. And upon this rock I will build my Church.\n\nLet us pray. O God, shepherd and ruler of all the faithful, look mercifully upon your servant N., whom you have willed to appoint shepherd over your Church. Grant him, we beseech you, that by word and example he may profit those over whom he has charge, so that, together with the flock committed to him, he may attain everlasting life. Through Christ our Lord. Amen.","la":"℣. Oremus pro Pontifice nostro N.\n℟. Dominus conservet eum, et vivificet eum, et beatum faciat eum in terra, et non tradat eum in animam inimicorum eius.\n\n℣. Tu es Petrus.\n℟. Et super hanc petram ædificabo Ecclesiam meam.\n\nOremus. Deus, omnium fidelium pastor et rector, famulum tuum N., quem pastorem Ecclesiæ tuæ præesse voluisti, propitius respice: da ei, quæsumus, verbo et exemplo, quibus præest, proficere; ut ad vitam, una cum grege sibi credito, perveniat sempiternam. Per Christum Dominum nostrum. Amen.","fr":"℣. Prions pour notre Souverain Pontife N.\n℟. Que le Seigneur le garde, qu’il lui conserve la vie, qu’il le rende heureux sur la terre et ne le livre pas à la volonté de ses ennemis.\n\n℣. Vous êtes Pierre.\n℟. Et sur cette pierre je bâtirai mon Église.\n\nPrions. Ô Dieu, pasteur et guide de tous les fidèles, regardez avec bienveillance votre serviteur N., que vous avez placé comme pasteur à la tête de votre Église. Accordez-lui, nous vous en prions, de faire progresser, par sa parole et son exemple, ceux qu’il gouverne, afin qu’il parvienne à la vie éternelle avec le troupeau qui lui a été confié. Par Jésus-Christ Notre-Seigneur. Ainsi soit-il.","source":"Roman Rite prayer for the Supreme Pontiff","sourceUrl":"https://www.vaticannews.va/en/prayers/prayer-for-the-pope.html","note":"","category":"saints","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":true,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Prayer for the Pope","witness":"Vatican News / Roman Missal prayer","url":"https://www.vaticannews.va/en/prayers/prayer-for-the-pope.html","quality":"VERIFIED_PRIMARY","visibility":1,"adaptation":"TRADITIONAL_LITURGICAL_FORM","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_SECONDARY"},"note":"The app retains the traditional Tu es Petrus versicle alongside the collect."},"sourceAuditVersion":"35.7"},"devotion_st_anthony_lost_items":{"id":"devotion_st_anthony_lost_items","title":"Si quæris miracula — St Anthony for Lost Things","titleFr":"Si quæris miracula — saint Antoine et les objets perdus","en":"℟. If, then, thou seekest miracles,\nDeath, error, all calamities,\nThe leprosy and demons flee,\nThe sick, by him made whole, arise.\n* The sea withdraws and fetters break,\nAnd withered limbs he doth restore,\nWhile treasures lost are found again,\nWhen young or old his help implore.\n\n℣. All dangers vanish from our path,\nOur direst needs do quickly flee:\nLet those who know repeat the theme:\nLet Paduans praise St. Anthony.\n* The sea withdraws and fetters break,\nAnd withered limbs he doth restore,\nWhile treasures lost are found again,\nWhen young or old his help implore.\n\nTo the Father, Son let glory be,\nAnd Holy Ghost eternally.\n* The sea withdraws and fetters break,\nAnd withered limbs he doth restore,\nWhile treasures lost are found again,\nWhen young or old his help implore.\n\n℣. Pray for us, O blessed Anthony.\n℟. That we may be made worthy of the promises of Christ.\n\nLet us pray.\nLet Thy Church, O God, be gladdened by the solemn commemoration of blessed Anthony Thy Confessor: that she may be evermore defended by Thy spiritual assistance and merit to possess everlasting joy. Through Christ our Lord. Amen.","la":"℟. Si quæris miracula,\nMors, error, calamitas,\nDæmon, lepra fugiunt,\nÆgri surgunt sani.\n* Cedunt mare, vincula;\nMembra resque perditas\nPetunt et accipiunt\nIuvenes et cani.\n\n℣. Pereunt pericula,\nCessat et necessitas:\nNarrent hi qui sentiunt,\nDicant Paduani.\n* Cedunt mare, vincula;\nMembra resque perditas\nPetunt et accipiunt\nIuvenes et cani.\n\nGloria Patri et Filio et Spiritui Sancto.\n* Cedunt mare, vincula;\nMembra resque perditas\nPetunt et accipiunt\nIuvenes et cani.\n\n℣. Ora pro nobis, beate Antoni.\n℟. Ut digni efficiamur promissionibus Christi.\n\nOremus.\nEcclesiam tuam, Deus, beati Antonii Confessoris tui commemoratio votiva lætificet: ut spiritualibus semper muniatur auxiliis et gaudiis perfrui mereatur æternis. Per Christum Dominum nostrum. Amen.","fr":"℟. Si vous cherchez des miracles,\nla mort, l’erreur, le malheur,\nle démon, la lèpre, s’enfuient ;\nles malades se lèvent guéris.\n* On voit céder la mer, et les chaînes se briser,\njeunes et vieux\nretrouver par la prière\nl’usage de leurs membres et les objets perdus.\n\n℣. Les dangers s’évanouissent,\nle besoin cesse :\nà ceux qui l’éprouvent de le raconter,\naux Padouans de le dire.\n* On voit céder la mer, et les chaînes se briser,\njeunes et vieux\nretrouver par la prière\nl’usage de leurs membres et les objets perdus.\n\nGloire au Père et au Fils et au Saint-Esprit.\n* On voit céder la mer, et les chaînes se briser,\njeunes et vieux\nretrouver par la prière\nl’usage de leurs membres et les objets perdus.\n\n℣. Priez pour nous, saint Antoine.\n℟. Afin que nous soyons rendus dignes des promesses de Jésus-Christ.\n\nPrions.\nQue la mémoire faite par nous du bienheureux Antoine votre confesseur soit pour votre Église, ô Dieu, une cause de joie ; qu’elle y trouve l’appui constant de vos grâces, et l’assurance du bonheur éternel. Par Jésus-Christ notre Seigneur. Ainsi soit-il.","source":"Si quæris miracula · Franciscan Office tradition · Raccolta no. 531","sourceUrl":"https://www.preces-latinae.org/thesaurus/Sancti/SAntoniusDePadova/SiQuaeris.html","note":"The inherited later prayer has been replaced by the historic miraculous responsory. Its text itself invokes the recovery of resque perditas / lost things; the Latin-English witness is Raccolta-attested, and the French witness follows the traditional parallel text.","category":"saints","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":true,"sourceStatus":"VERIFIED_SECONDARY","provenance":{"work":"Si quæris miracula","witness":"Historic miraculous responsory of St Anthony · Raccolta no. 531","url":"https://www.preces-latinae.org/thesaurus/Sancti/SAntoniusDePadova/SiQuaeris.html","quality":"VERIFIED_SECONDARY","visibility":1,"adaptation":"VERBATIM","languages":{"en":"VERIFIED_SECONDARY","la":"VERIFIED_SECONDARY","fr":"VERIFIED_SECONDARY"},"note":"Latin and English follow the historic responsory witness; French follows the traditional parallel text published by Introibo.","frenchWitnessUrl":"https://introibo.fr/13-06-St-Antoine-de-Padoue"},"sourceAuditVersion":"41.4"},"sacred_heart_short_prayer":{"id":"sacred_heart_short_prayer","title":"Act of Reparation to the Sacred Heart of Jesus","titleFr":"Acte de réparation au Sacré-Cœur de Jésus","en":"Most Sweet Jesus, whose overflowing charity for men is requited by so much forgetfulness, negligence and contempt, behold us prostrate before Thee, eager to repair by a special act of homage the cruel indifference and injuries to which Thy loving Heart is everywhere subjected.\n\nMindful, alas, that we ourselves have had a share in such great indignities, which we now deplore from the depths of our hearts, we humbly ask Thy pardon and declare our readiness to atone by voluntary expiation, not only for our own personal offenses, but also for the sins of those who, straying far from the path of salvation, refuse in their obstinate infidelity to follow Thee, their Shepherd and Leader, or, renouncing the promises of their baptism, have cast off the sweet yoke of Thy Law.\n\nWe are now resolved to expiate each and every deplorable outrage committed against Thee; we are now determined to make amends for the manifold offenses against Christian modesty in unbecoming dress and behavior, for all the foul seductions laid to ensnare the feet of the innocent, for the frequent violations of Sundays and holydays, and the shocking blasphemies uttered against Thee and Thy Saints. We wish also to make amends for the insults to which Thy Vicar on earth and Thy priests are subjected, for the profanation, by conscious neglect or terrible acts of sacrilege, of the very Sacrament of Thy Divine Love, and lastly for the public crimes of nations who resist the rights and teaching authority of the Church which Thou hast founded.\n\nWould that we were able to wash away such abominations with our blood.\n\nWe now offer, in reparation for these violations of Thy Divine Honor, the satisfaction Thou once made to Thy Eternal Father on the Cross and which Thou continuest to renew daily on our altars; we offer it in union with the acts of atonement of Thy Virgin Mother and all the Saints and of the pious faithful on earth; and we sincerely promise to make recompense, as far as we can with the help of Thy grace, for all neglect of Thy great love and for the sins we and others have committed in the past. Henceforth, we will live a life of unswerving faith, of purity of conduct, of perfect observance of the precepts of the Gospel and especially that of charity. We promise to the best of our power to prevent others from offending Thee and to bring as many as possible to follow Thee.\n\nO loving Jesus, through the intercession of the Blessed Virgin Mother, our model in reparation, deign to receive the voluntary offering we make of this act of expiation; and by the crowning gift of perseverance keep us faithful unto death in our duty and the allegiance we owe to Thee, so that we may all one day come to that happy home, where with the Father and the Holy Spirit Thou livest and reignest, God, forever and ever. Amen.","la":"Iesu dulcissime, cuius effusa in homines caritas, tanta oblivione, neglegentia, contemptione, ingratissime rependitur, en nos, ante conspectum tuum provoluti, tam nefariam hominum socordiam iniuriasque, quibus undique amantissimum Cor tuum afficitur, peculiari honore resarcire contendimus.\n\nAttamen, memores tantae nos quoque indignitatis non expertes aliquando fuisse, indeque vehementissimo dolore commoti, tuam in primis misericordiam nobis imploramus, parati, voluntaria expiatione compensare flagitia non modo quae ipsi patravimus, sed etiam illorum, qui, longe a salutis via aberrantes vel te pastorem ducemque sectari detrectant, in sua infidelitate obstinati, vel, baptismatis promissa conculcantes, suavissimum tuae legis iugum excusserunt.\n\nQuae deploranda crimina, cum universa expiare contendimus, tum nobis singula resarcienda proponimus: vitae cultusque immodestiam atque turpitudines, tot corruptelae pedicas innocentium animis instructas, dies festos violatos, exsecranda in te tuosque Sanctos iactata maledicta atque in tuum Vicarium ordinemque sacerdotalem convicia irrogata, ipsum denique amoris divini Sacramentum vel neglectum vel horrendis sacrilegiis profanatum, publica postremo nationum delicta, quae Ecclesiae a te institutae iuribus magisterioque reluctantur.\n\nQuae utinam crimina sanguine ipsi nostro eluere possemus! Interea ad violatum divinum honorem resarciendum, quam Tu olim Patri in Cruce satisfactionem obtulisti quamque cotidie in altaribus renovare pergis, hanc eamdem nos tibi praestamus, cum Virginis Matris, omnium Sanctorum, piorum quoque fidelium expiationibus coniunctam, ex animo spondentes, cum praeterita nostra aliorumque peccata ac tanti amoris incuriam firma fide, candidis vitae moribus, perfecta legis evangelicae, caritatis potissimum, observantia, quantum in nobis erit, gratia tua favente, nos esse compensaturos, tum iniurias tibi inferendas pro viribus prohibituros, et quam plurimos potuerimus ad tui sequelam convocaturos.\n\nExcipias, quaesumus, benignissime Iesu, beata Virgine Maria Reparatrice intercedente, voluntarium huius expiationis obsequium nosque in officio tuique servitio fidissimos ad mortem usque velis, magno illo perseverantiae munere, continere, ut ad illam tandem patriam perveniamus omnes, ubi Tu cum Patre et Spiritu Sancto vivis et regnas in saecula saeculorum. Amen.","fr":"Très doux Jésus, dont l’immense amour pour les hommes a été avec tant d’ingratitude payé par l’oubli, la négligence, le mépris, voici que, prosternés devant vos autels, nous voulons réparer par des témoignages particuliers d’honneur une froideur si indigne et les injures qui blessent de toutes parts votre Cœur très aimant.\n\nNous souvenant toutefois que nous n’avons pas toujours été, nous non plus, exempts de cette indignité et en ressentant une très profonde douleur, nous implorons tout d’abord sur nous votre miséricorde, disposés à réparer par une expiation volontaire non seulement les péchés que nous avons commis nous-mêmes, mais encore les fautes de ceux qui, égarés loin de la voie du salut, refusent de vous suivre comme leur pasteur et leur guide, s’obstinant dans leur infidélité, ou qui, reniant les promesses de leur baptême, ont secoué le joug très suave de votre loi.\n\nCes crimes déplorables que nous voulons expier tous, nous nous proposons aussi de les réparer chacun en particulier : l’immodestie et les hontes de la conduite et des vêtements ; les embûches tendues par la corruption aux âmes innocentes, la violation des fêtes, les outrages odieux lancés contre vous et vos saints, ainsi que les insultes adressées à votre Vicaire et à l’ordre sacerdotal, la négligence à l’égard du Sacrement du divin amour ou sa profanation par d’horribles sacrilèges, enfin les crimes publics des nations qui combattent les droits et le magistère de l’Église que vous avez instituée.\n\nQue ne nous est-il donné de pouvoir laver ces crimes de notre sang ! Pour réparer l’honneur divin outragé, nous vous présentons, unie aux expiations de la Vierge Marie, de tous les saints et des fidèles pieux, l’expiation que vous avez un jour offerte au Père sur la croix et que vous continuez de renouveler chaque jour sur les autels ; nous vous promettons de tout notre Cœur de réparer pour autant qu’il sera en nous et avec le secours de votre grâce nos fautes passées comme celles des autres et une si grande négligence de votre amour par une foi inébranlable, par une vie pure, par l’observation parfaite de la loi évangélique, en particulier de la charité, d’empêcher selon nos forces les offenses qui s’adresseraient à vous et d’amener le plus d’hommes possible à votre suite.\n\nTrès bon Jésus, recevez, nous vous en prions, par l’intercession de la bienheureuse Vierge Marie Réparatrice, l’hommage volontaire de notre expiation et daignez, par le don précieux de la persévérance, nous garder fidèles jusqu’à la mort dans votre obéissance et votre service, afin que nous parvenions enfin tous à cette patrie où vous vivez et régnez, vrai Dieu, avec le Père et l’Esprit-Saint, dans les siècles des siècles. Ainsi soit-il.","source":"Pius XI · Miserentissimus Redemptor · Act of Reparation · 1928","sourceUrl":"https://www.vatican.va/roman_curia/tribunals/apost_penit/documents/rc_trib_appen_doc_20020826_enchiridion-indulgentiarum_lt.html","note":"The inherited short prayer and doubtful Raccolta numbering have been replaced by the officially promulgated Iesu dulcissime Act of Reparation. Latin follows the Vatican Enchiridion; English and French use established Catholic translations.","category":"hearts","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":true,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Iesu dulcissime · Actus reparationis","witness":"Apostolic Penitentiary · Enchiridion Indulgentiarum; prayer prescribed by Pius XI","url":"https://www.vatican.va/roman_curia/tribunals/apost_penit/documents/rc_trib_appen_doc_20020826_enchiridion-indulgentiarum_lt.html","quality":"VERIFIED_PRIMARY","visibility":1,"adaptation":"VERBATIM","languages":{"en":"VERIFIED_SECONDARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_SECONDARY"},"note":"Latin is the official Vatican text. English follows an established traditional Catholic translation; French follows the ICRSP text associated with Pius XI’s Miserentissimus Redemptor.","englishWitnessUrl":"https://www.carmelitesofrochester.org/act-of-reparation-to-the-sacred-heart","frenchWitnessUrl":"https://www.icrsp.org/Pages/magistere.php?groupe=Pie+XI&nom=miserentissimus-deus"},"sourceAuditVersion":"41.4"},"sacred_heart_aspiration_trust":{"id":"sacred_heart_aspiration_trust","title":"Sacred Heart Aspiration","titleFr":"Aspiration au Sacré-Cœur","en":"Most Sacred Heart of Jesus, I place all my trust in you.","la":"Cor Iesu sacratissimum, in te confido.","fr":"Cœur Sacré de Jésus, j’ai confiance en toi.","source":"","sourceUrl":"","note":"","category":"hearts","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_SECONDARY","provenance":{"work":"Sacred Heart aspiration","witness":"Widely attested devotional aspiration; USCCB Sacred Heart novena witness","url":"https://www.usccb.org/novena-sacred-heart-jesus","quality":"VERIFIED_SECONDARY","visibility":0,"adaptation":"TRADITIONAL_VARIANT","languages":{"en":"VERIFIED_SECONDARY","la":"VERIFIED_SECONDARY","fr":"VERIFIED_SECONDARY"},"note":"Short aspiration; visible source suppressed."},"sourceAuditVersion":"35.7"},"foundations_eternal_rest":{"id":"foundations_eternal_rest","title":"Eternal Rest (Requiem)","titleFr":"Repos éternel","en":"Eternal rest grant unto them, O Lord, and let perpetual light shine upon them. May they rest in peace. Amen.","la":"Requiem aeternam dona eis, Domine, et lux perpetua luceat eis. Requiescant in pace. Amen.","fr":"Donne-leur, Seigneur, le repos éternel, et que la lumière éternelle brille sur eux. Qu’ils reposent en paix. Amen.","source":"","sourceUrl":"","note":"","category":"dead","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Eternal Rest","witness":"Compendium of the Catechism of the Catholic Church · Appendix A","url":"https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_en.html","quality":"VERIFIED_PRIMARY","visibility":0,"adaptation":"VERBATIM","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_PRIMARY"},"note":"Common prayer; provenance retained internally and not shown by default."},"sourceAuditVersion":"35.7"},"dead_de_profundis":{"id":"dead_de_profundis","title":"De Profundis — Psalm 129","titleFr":"De profundis · Psaume 129","en":"Out of the depths I have cried to thee, O Lord: Lord, hear my voice. Let thine ears be attentive to the voice of my supplication. If thou, O Lord, wilt mark iniquities: Lord, who shall stand it? For with thee there is merciful forgiveness; and by reason of thy law I have waited for thee, O Lord. My soul hath relied on his word; my soul hath hoped in the Lord. From the morning watch even until night, let Israel hope in the Lord. Because with the Lord there is mercy, and with him plentiful redemption. And he shall redeem Israel from all his iniquities.\n\n℣. Eternal rest grant unto them, O Lord.\n℟. And let perpetual light shine upon them.\n\n℣. May they rest in peace.\n℟. Amen.","la":"De profundis clamavi ad te, Domine; Domine, exaudi vocem meam. Fiant aures tuæ intendentes in vocem deprecationis meæ. Si iniquitates observaveris, Domine, Domine, quis sustinebit? Quia apud te propitiatio est; et propter legem tuam sustinui te, Domine. Sustinuit anima mea in verbo eius; speravit anima mea in Domino. A custodia matutina usque ad noctem, speret Israel in Domino. Quia apud Dominum misericordia, et copiosa apud eum redemptio. Et ipse redimet Israel ex omnibus iniquitatibus eius.\n\n℣. Requiem æternam dona eis, Domine.\n℟. Et lux perpetua luceat eis.\n\n℣. Requiescant in pace.\n℟. Amen.","fr":"Des profondeurs, je crie vers vous, Seigneur; Seigneur, écoutez ma voix. Que vos oreilles soient attentives à la voix de ma supplication. Si vous retenez les iniquités, Seigneur, Seigneur, qui pourra subsister? Mais auprès de vous se trouve le pardon; à cause de votre loi, je vous ai attendu, Seigneur. Mon âme s’est appuyée sur sa parole; mon âme a espéré dans le Seigneur. Depuis la veille du matin jusqu’à la nuit, qu’Israël espère dans le Seigneur. Car auprès du Seigneur est la miséricorde, et auprès de lui une abondante rédemption. C’est lui qui rachètera Israël de toutes ses iniquités.\n\n℣. Donnez-leur, Seigneur, le repos éternel.\n℟. Et que la lumière perpétuelle luise sur eux.\n\n℣. Qu’ils reposent en paix.\n℟. Ainsi soit-il.","source":"","sourceUrl":"","note":"","category":"dead","implementationOrigin":"Lab-ora RC50.1 · inherited traditional prayer corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"De Profundis · Psalm 129 (Vulgate)","witness":"F. X. Lasance · With God · Evening Prayers","url":"https://en.wikisource.org/wiki/With_God/Evening_Prayers","quality":"VERIFIED_PRIMARY","visibility":0,"adaptation":"TYPOGRAPHY_NORMALIZED","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_SECONDARY"},"note":"Psalm and traditional prayers for the faithful departed."},"sourceAuditVersion":"35.7"},"devotion_litany_st_joseph":{"id":"devotion_litany_st_joseph","title":"Litany of Saint Joseph","titleFr":"Litanies de saint Joseph","en":"Lord, have mercy.\nChrist, have mercy.\nLord, have mercy.\n\nChrist, hear us.\nChrist, graciously hear us.\n\nGod the Father in heaven, have mercy on us.\nGod the Son, Redeemer of the world, have mercy on us.\nGod the Holy Spirit, have mercy on us.\nHoly Trinity, one God, have mercy on us.\n\nHoly Mary, pray for us.\nSaint Joseph, pray for us.\nIllustrious son of David, pray for us.\nLight of Patriarchs, pray for us.\nSpouse of the Mother of God, pray for us.\nGuardian of the Redeemer, pray for us.\nPure Guardian of the Virgin, pray for us.\nProvider for the Son of God, pray for us.\nZealous defender of Christ, pray for us.\nServant of Christ, pray for us.\nMinister of salvation, pray for us.\nHead of the Holy Family, pray for us.\nJoseph, most just, pray for us.\nJoseph, most chaste, pray for us.\nJoseph, most prudent, pray for us.\nJoseph, most brave, pray for us.\nJoseph, most obedient, pray for us.\nJoseph, most loyal, pray for us.\nMirror of patience, pray for us.\nLover of poverty, pray for us.\nModel for workers, pray for us.\nGlory of family life, pray for us.\nGuardian of virgins, pray for us.\nCornerstone of families, pray for us.\nSupport in difficulties, pray for us.\nComfort of the sorrowing, pray for us.\nHope of the sick, pray for us.\nPatron of exiles, pray for us.\nPatron of the afflicted, pray for us.\nPatron of the poor, pray for us.\nPatron of the dying, pray for us.\nTerror of demons, pray for us.\nProtector of the Holy Church, pray for us.\n\nLamb of God, you take away the sins of the world, spare us, O Lord.\nLamb of God, you take away the sins of the world, hear us, O Lord.\nLamb of God, you take away the sins of the world, have mercy on us.\n\n℣. He made him master of his house.\n℟. And ruler of all his possessions.\n\nLet us pray.\nO God, who in your inexpressible providence were pleased to choose Saint Joseph as spouse of your most holy Mother, grant, we pray, that we, who revere him as our protector on earth, may be worthy of his heavenly intercession. Who live and reign for ever and ever.\n℟. Amen.","la":"Kyrie, eleison.\nChriste, eleison.\nKyrie, eleison.\nChriste, audi nos.\nChriste, exaudi nos.\n\nPater de cælis, Deus, miserere nobis.\nFili, Redemptor mundi, Deus, miserere nobis.\nSpiritus Sancte, Deus, miserere nobis.\nSancta Trinitas, unus Deus, miserere nobis.\n\nSancta Maria, ora pro nobis.\nSancte Ioseph, ora pro nobis.\nProles David inclita, ora pro nobis.\nLumen Patriarcharum, ora pro nobis.\nDei Genetricis Sponse, ora pro nobis.\nCustos Redemptoris, ora pro nobis.\nCustos pudice Virginis, ora pro nobis.\nFilii Dei nutricie, ora pro nobis.\nChristi defensor sedule, ora pro nobis.\nServe Christi, ora pro nobis.\nMinister salutis, ora pro nobis.\nAlmæ Familiæ præses, ora pro nobis.\nIoseph iustissime, ora pro nobis.\nIoseph castissime, ora pro nobis.\nIoseph prudentissime, ora pro nobis.\nIoseph fortissime, ora pro nobis.\nIoseph obœdientissime, ora pro nobis.\nIoseph fidelissime, ora pro nobis.\nSpeculum patientiæ, ora pro nobis.\nAmator paupertatis, ora pro nobis.\nExemplar opificum, ora pro nobis.\nDecus vitæ domesticæ, ora pro nobis.\nCustos virginum, ora pro nobis.\nFamiliarum columen, ora pro nobis.\nFulcimen in difficultatibus, ora pro nobis.\nSolatium miserorum, ora pro nobis.\nSpes ægrotantium, ora pro nobis.\nPatrone exsulum, ora pro nobis.\nPatrone afflictorum, ora pro nobis.\nPatrone pauperum, ora pro nobis.\nPatrone morientium, ora pro nobis.\nTerror dæmonum, ora pro nobis.\nProtector sanctæ Ecclesiæ, ora pro nobis.\n\nAgnus Dei, qui tollis peccata mundi, parce nobis, Domine.\nAgnus Dei, qui tollis peccata mundi, exaudi nos, Domine.\nAgnus Dei, qui tollis peccata mundi, miserere nobis.\n\n℣. Constituit eum dominum domus suæ.\n℟. Et principem omnis possessionis suæ.\n\nOremus. Deus, qui ineffabili providentia beatum Ioseph sanctissimæ Genetricis tuæ Sponsum eligere dignatus es: præsta, quæsumus; ut quem protectorem veneramur in terris, intercessorem habere mereamur in cælis. Qui vivis et regnas in sæcula sæculorum. Amen.","fr":"Seigneur, ayez pitié de nous.\nJésus-Christ, ayez pitié de nous.\nSeigneur, ayez pitié de nous.\nJésus-Christ, écoutez-nous.\nJésus-Christ, exaucez-nous.\n\nPère céleste, qui êtes Dieu, ayez pitié de nous.\nFils, Rédempteur du monde, qui êtes Dieu, ayez pitié de nous.\nEsprit-Saint, qui êtes Dieu, ayez pitié de nous.\nTrinité Sainte, qui êtes un seul Dieu, ayez pitié de nous.\n\nSainte Marie, priez pour nous.\nSaint Joseph, priez pour nous.\nIllustre descendant de David, priez pour nous.\nLumière des Patriarches, priez pour nous.\nÉpoux de la Mère de Dieu, priez pour nous.\nGardien du Rédempteur, priez pour nous.\nChaste gardien de la Vierge, priez pour nous.\nNourricier du Fils de Dieu, priez pour nous.\nZélé défenseur de Jésus, priez pour nous.\nServiteur du Christ, priez pour nous.\nMinistre du Salut, priez pour nous.\nChef de la Sainte Famille, priez pour nous.\nJoseph très juste, priez pour nous.\nJoseph très chaste, priez pour nous.\nJoseph très prudent, priez pour nous.\nJoseph très courageux, priez pour nous.\nJoseph très obéissant, priez pour nous.\nJoseph très fidèle, priez pour nous.\nMiroir de patience, priez pour nous.\nAmi de la pauvreté, priez pour nous.\nModèle des travailleurs, priez pour nous.\nGloire de la vie de famille, priez pour nous.\nGardien des vierges, priez pour nous.\nSoutien des familles, priez pour nous.\nSoutien dans les difficultés, priez pour nous.\nConsolation des malheureux, priez pour nous.\nEspérance des malades, priez pour nous.\nPatron des exilés, priez pour nous.\nPatron des affligés, priez pour nous.\nPatron des pauvres, priez pour nous.\nPatron des mourants, priez pour nous.\nTerreur des démons, priez pour nous.\nProtecteur de la sainte Église, priez pour nous.\n\nAgneau de Dieu, qui effacez les péchés du monde, pardonnez-nous, Seigneur.\nAgneau de Dieu, qui effacez les péchés du monde, exaucez-nous, Seigneur.\nAgneau de Dieu, qui effacez les péchés du monde, ayez pitié de nous.\n\n℣. Il l'a établi le chef de sa maison.\n℟. Et l'intendant de tous ses biens.\n\nPrions. Ô Dieu, qui, par une providence ineffable, avez daigné choisir le bienheureux Joseph pour être l'époux de votre sainte Mère, faites, nous vous en prions, que, l'honorant ici-bas comme protecteur, nous méritions de l'avoir pour intercesseur dans le ciel. Vous qui vivez et régnez dans les siècles des siècles. Ainsi soit-il.","category":"saints","source":"Current 2021 invocation set. English: AELF Committee on Divine Worship approved translation, freely publishable. Latin: Holy See current text. French: retained as a traditional vernacular rendering with the seven 2021 titles; not represented as an episcopal-conference official recension pending exact source lock.","sourceUrl":"https://www.usccb.org/prayers/litany-saint-joseph","note":""},"devotion_ad_te_beate_ioseph":{"id":"devotion_ad_te_beate_ioseph","title":"To Thee, O Blessed Joseph","titleFr":"À vous, bienheureux Joseph","en":"To thee, O blessed Joseph, we have recourse in our affliction, and having implored the help of thy thrice holy Spouse, we now, with hearts filled with confidence, earnestly beg thee also to take us under thy protection.\n\nBy that charity wherewith thou wert united to the Immaculate Virgin Mother of God, and by that fatherly love with which thou didst cherish the Child Jesus, we beseech thee and we humbly pray that thou wilt look down with gracious eye upon that inheritance which Jesus Christ purchased by His blood, and wilt succor us in our need by thy power and strength.\n\nDefend, O most watchful guardian of the Holy Family, the chosen offspring of Jesus Christ. Keep from us, O most loving Father, all blight of error and corruption. Aid us from on high, most valiant defender, in this conflict with the powers of darkness. And even as of old thou didst rescue the Child Jesus from the peril of His life, so now defend God's Holy Church from the snares of the enemy and from all adversity.\n\nShield us ever under thy patronage, that, following thine example and strengthened by thy help, we may live a holy life, die a happy death, and attain to everlasting bliss in Heaven. Amen.","la":"Ad te, beate Ioseph, in tribulatione nostra confugimus, atque, implorato Sponsæ tuæ sanctissimæ auxilio, patrocinium quoque tuum fidenter exposcimus.\n\nPer eam, quæsumus, quæ te cum immaculata Virgine Dei Genetrice coniunxit, caritatem, perque paternum, quo Puerum Iesum amplexus es, amorem, supplices deprecamur, ut ad hereditatem, quam Iesus Christus acquisivit Sanguine suo, benignus respicias, ac necessitatibus nostris tua virtute et ope succurras.\n\nTuere, o Custos providentissime divinæ Familiæ, Iesu Christi sobolem electam; prohibe a nobis, amantissime Pater, omnem errorum ac corruptelarum luem; propitius nobis, sospitator noster fortissime, in hoc cum potestate tenebrarum certamine e cælo adesto; et sicut olim Puerum Iesum e summo eripuisti vitæ discrimine, ita nunc Ecclesiam sanctam Dei ab hostilibus insidiis atque ab omni adversitate defende: nosque singulos perpetuo tege patrocinio, ut ad tui exemplar et ope tua suffulti, sancte vivere, pie emori, sempiternamque in cælis beatitudinem assequi possimus. Amen.","fr":"Nous recourons à vous dans notre tribulation, ô bienheureux Joseph : et, après avoir imploré le secours de votre sainte Épouse, nous sollicitons aussi avec confiance votre patronage.\n\nPar l’affection qui vous a uni à la Vierge Immaculée, Mère de Dieu ; par l’amour paternel dont vous avez entouré l’Enfant-Jésus, nous vous supplions de regarder avec bonté l’héritage que Jésus-Christ a conquis au prix de son sang, et de nous assister de votre puissance et de votre secours dans nos besoins.\n\nProtégez, ô très sage gardien de la divine Famille, la race élue de Jésus-Christ. Préservez-nous, ô Père très aimant, de toute souillure d’erreur et de corruption ; soyez-nous favorable, ô notre très puissant libérateur. Du haut du ciel, assistez-nous dans le combat que nous livrons à la puissance des ténèbres ; et de même que vous avez arraché autrefois l’Enfant-Jésus au péril de la mort, défendez aujourd’hui la sainte Église de Dieu des embûches de l’ennemi et de toute adversité.\n\nCouvrez chacun de nous de votre perpétuelle protection, afin que, à votre exemple et soutenus par votre secours, nous puissions vivre saintement, pieusement mourir, et obtenir la béatitude éternelle. Ainsi soit-il.","category":"saints","source":"Prayer attached by Leo XIII to Quamquam pluries (1889). Latin is retained as the canonical traditional text; English follows the historical Holy See translation; French follows a historical Catholic translation.","sourceUrl":"https://www.vatican.va/content/leo-xiii/en/encyclicals/documents/hf_l-xiii_enc_15081889_quamquam-pluries.html","note":""},"traditional_veni_sancte_sequence":{"id":"traditional_veni_sancte_sequence","title":"Veni Sancte Spiritus · Pentecost Sequence","titleFr":"Veni Sancte Spiritus","en":"Holy Spirit! Lord of light!\nFrom Thy clear celestial height,\nThy pure beaming radiance give.\n\nCome, Thou Father of the poor!\nCome, with treasures which endure!\nCome, Thou Light of all that live!\n\nThou, of all consolers best,\nVisiting the troubled breast,\nDost refreshing peace bestow.\n\nThou in toil art comfort sweet;\nPleasant coolness in the heat;\nSolace in the midst of woe.\n\nLight immortal! Light Divine!\nVisit Thou these hearts of Thine,\nAnd our inmost being fill.\n\nIf Thou take Thy grace away,\nNothing pure in man will stay;\nAll his good is turned to ill.\n\nHeal our wounds—our strength renew;\nOn our dryness pour Thy dew;\nWash the stains of guilt away.\n\nBend the stubborn heart and will;\nMelt the frozen, warm the chill;\nGuide the steps that go astray.\n\nThou, on those who evermore\nThee confess and Thee adore,\nIn Thy sevenfold gifts, descend.\n\nGive them comfort when they die;\nGive them life with Thee on high;\nGive them joys which never end. Amen.","la":"Veni, Sancte Spiritus,\net emitte cælitus\nlucis tuæ radium.\n\nVeni, Pater pauperum,\nveni, dator munerum,\nveni, lumen cordium.\n\nConsolator optime,\ndulcis hospes animæ,\ndulce refrigerium.\n\nIn labore requies,\nin æstu temperies,\nin fletu solatium.\n\nO lux beatissima,\nreple cordis intima\ntuorum fidelium.\n\nSine tuo numine\nnihil est in homine,\nnihil est innoxium.\n\nLava quod est sordidum,\nriga quod est aridum,\nsana quod est saucium.\n\nFlecte quod est rigidum,\nfove quod est frigidum,\nrege quod est devium.\n\nDa tuis fidelibus\nin te confidentibus\nsacrum septenarium.\n\nDa virtutis meritum,\nda salutis exitum,\nda perenne gaudium. Amen.","fr":"Viens, Esprit-Saint,\net lance du ciel\nun rayon de tes feux.\n\nViens, Père des pauvres,\nviens, distributeur des trésors,\nviens, lumière des cœurs.\n\nConsolateur par excellence,\nhôte aimable des âmes,\ndoux rafraîchissement.\n\nRepos dans le travail,\nzéphyr dans la chaleur,\nsoulagement dans les pleurs.\n\nÔ lumière bienheureuse,\nremplis de tes douceurs\nles cœurs de tes fidèles.\n\nSans ton secours\nil n’y a rien dans l’homme,\nrien qui soit innocent.\n\nLave ce qui est sali,\narrose ce qui est aride,\nguéris ce qui est malade.\n\nRends souple ce qui est inflexible,\nréchauffe ce qui est glacé,\nredresse ce qui est dévié.\n\nDonne à tes fidèles\nqui se confient à toi\nles sept dons sacrés.\n\nDonne-nous le mérite de la vertu,\ndonne-nous la mort du juste,\ndonne-nous le bonheur éternel. Ainsi soit-il.","category":"holyghost","source":"Traditional Pentecost Sequence, also used devotionally to invoke the Holy Spirit. Latin is the received sequence; English is the public-domain Caswall translation printed in the 1857 Raccolta; French is a historical public-domain translation (Douniol, 1858).","sourceUrl":"https://en.wikisource.org/wiki/The_Raccolta_%281857%29/The_Hymn%2C_%22Veni_Creator_Spiritus%22%2C_and_the_Sequence%2C_%22Veni_Sancte_piritus%22","note":""},"dead_fidelium_deus":{"id":"dead_fidelium_deus","title":"Prayer for All the Faithful Departed","titleFr":"Prière pour tous les fidèles défunts","en":"O God, the Creator and Redeemer of all the faithful, grant to the souls of thy servants departed the remission of all their sins; that, through pious supplications, they may obtain the pardon which they have always desired: who livest and reignest, world without end. Amen.","la":"Fidelium Deus omnium, Conditor et Redemptor, animabus famulorum famularumque tuarum remissionem cunctorum tribue peccatorum: ut indulgentiam, quam semper optaverunt, piis supplicationibus consequantur. Qui vivis et regnas in sæcula sæculorum. Amen.","fr":"Ô Dieu, Créateur et Rédempteur de tous les fidèles, accordez aux âmes de vos serviteurs et de vos servantes la rémission de tous leurs péchés, afin que, par de pieuses supplications, elles obtiennent le pardon qu’elles ont toujours désiré. Vous qui vivez et régnez dans les siècles des siècles. Ainsi soit-il.","category":"dead","source":"Traditional Roman collect for all the faithful departed. English and French are historical Catholic translations; Latin is the received traditional text.","sourceUrl":"https://en.wikisource.org/wiki/The_Catholic_Prayer_Book_and_Manual_of_Meditations/Prayers_for_the_Dead","note":""},"dead_eternal_rest_singular":{"id":"dead_eternal_rest_singular","title":"Eternal Rest · for one deceased person","titleFr":"Repos éternel · pour un défunt","en":"Eternal rest grant unto him or her, O Lord, and let perpetual light shine upon him or her. May he or she rest in peace. Amen.","la":"Requiem æternam dona ei, Domine, et lux perpetua luceat ei. Requiescat in pace. Amen.","fr":"Donnez-lui, Seigneur, le repos éternel, et que la lumière perpétuelle l’illumine. Qu’il ou elle repose en paix. Ainsi soit-il.","category":"dead","source":"Traditional singular form of Requiem aeternam for one deceased person.","sourceUrl":"https://www.ctsbooks.org/prayers-for-the-dead/","note":""},"sub_tuum":{"id":"sub_tuum","title":"Sub Tuum Praesidium","titleFr":"Sous l’abri de votre miséricorde","category":"marian","source":"","sourceUrl":"","note":"","en":"We fly to your patronage, O holy Mother of God. Despise not our prayers in our necessities, but deliver us from all dangers, O ever glorious and Blessed Virgin.","la":"Sub tuum præsidium confugimus, sancta Dei Genetrix; nostras deprecationes ne despicias in necessitatibus nostris, sed a periculis cunctis libera nos semper, Virgo gloriosa et benedicta.","fr":"Sous l’abri de votre miséricorde, nous nous réfugions, sainte Mère de Dieu. Ne méprisez pas nos prières quand nous sommes dans l’épreuve, mais de tous les dangers délivrez-nous toujours, Vierge glorieuse et bénie.","implementationOrigin":"Ancient Marian antiphon · Lab-ora Rosary corpus","implementationOriginUrl":"https://fulcanelli13.github.io/lab-ora/","sourceVisible":false,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Sub tuum praesidium","witness":"Holy See Press Office · ancient Marian invocation","url":"https://press.vatican.va/content/salastampa/en/bollettino/pubblico/2018/09/29/180929d.html","quality":"VERIFIED_PRIMARY","visibility":0,"adaptation":"TRADITIONAL_TRANSLATION","languages":{"en":"VERIFIED_PRIMARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_SECONDARY"},"note":"Ancient Marian antiphon; no visible source needed in ordinary use."},"sourceAuditVersion":"35.7"},"benediction_adoremus_ps116":{"id":"benediction_adoremus_ps116","title":"Adoremus in aeternum · Psalm 116/117","titleFr":"Adorons à jamais · Psaume 116/117","category":"eucharistic","source":"Traditional Benediction","sourceUrl":"https://en.wikisource.org/wiki/Blessed_Sacrament_Book","note":"","en":"Let us adore for ever the Most Holy Sacrament.\n\nO praise the Lord, all ye nations: praise Him, all ye people.\nFor His mercy is confirmed upon us; and the truth of the Lord remaineth for ever.\n\nGlory be to the Father, and to the Son, and to the Holy Ghost.\nAs it was in the beginning, is now, and ever shall be. Amen.\n\nLet us adore for ever the Most Holy Sacrament.","la":"Adorémus in aetérnum sanctíssimum Sacraméntum.\n\nLaudáte Dóminum, omnes gentes: laudáte eum, omnes pópuli.\nQuóniam confirmáta est super nos misericórdia ejus: et véritas Dómini manet in aetérnum.\n\nGlória Patri, Fílio, et Spirítui Sancto.\nSicut erat in princípio, et nunc, et semper, et in sæcula sæculórum. Amen.\n\nAdorémus in aetérnum sanctíssimum Sacraméntum.","fr":"Adorons à jamais le Très Saint Sacrement.\n\nLouez le Seigneur tous les peuples, louez le Seigneur toutes les nations,\nsa miséricorde pour nous a été confirmée et la fidélité du Seigneur demeure à jamais.\n\nGloire au Père, et au Fils, et au Saint-Esprit.\nComme il était au commencement, maintenant et toujours, pour les siècles des siècles. Amen.\n\nAdorons à jamais le Très Saint Sacrement.","implementationOrigin":"Traditional Benediction/reposition corpus · imported from Lab-ora RC50.1","implementationOriginUrl":"https://laudatedominum.net/files/mis.pdf","sourceVisible":true,"sourceStatus":"VERIFIED_PRIMARY","provenance":{"work":"Adoremus in aeternum + Psalm 116","witness":"Lasance · Blessed Sacrament Book · 1913; traditional Benediction corpus","url":"https://en.wikisource.org/wiki/Blessed_Sacrament_Book","quality":"VERIFIED_PRIMARY","visibility":1,"adaptation":"TRADITIONAL_ASSEMBLY","languages":{"en":"VERIFIED_SECONDARY","la":"VERIFIED_PRIMARY","fr":"VERIFIED_SECONDARY"},"note":"The antiphon is directly witnessed by Lasance; Psalm 116/117 is the traditional accompanying psalm."},"sourceAuditVersion":"35.7"},"litany_loreto_1962":{"id":"litany_loreto_1962","title":"Litany of Loreto · 1962-era form","titleFr":"Litanies de Lorette · forme de 1962","category":"marian","source":"Holy See Litany of Loreto; 1962-era form omits later invocations","sourceUrl":"https://www.vatican.va/special/rosary/documents/litanie-lauretane_en.html","note":"Later invocations are shown separately so the older TLM-era form is not silently modernized.","en":"Lord, have mercy on us.\nChrist, have mercy on us.\nLord, have mercy on us.\nChrist, hear us.\nChrist, graciously hear us.\n\nGod the Father of Heaven, have mercy on us.\nGod the Son, Redeemer of the world, have mercy on us.\nGod the Holy Spirit, have mercy on us.\nHoly Trinity, one God, have mercy on us.\n\nHoly Mary — Pray for us.\nHoly Mother of God — Pray for us.\nHoly Virgin of virgins — Pray for us.\nMother of Christ — Pray for us.\nMother of divine grace — Pray for us.\nMother most pure — Pray for us.\nMother most chaste — Pray for us.\nMother inviolate — Pray for us.\nMother undefiled — Pray for us.\nMother most amiable — Pray for us.\nMother admirable — Pray for us.\nMother of good counsel — Pray for us.\nMother of our Creator — Pray for us.\nMother of our Saviour — Pray for us.\nVirgin most prudent — Pray for us.\nVirgin most venerable — Pray for us.\nVirgin most renowned — Pray for us.\nVirgin most powerful — Pray for us.\nVirgin most merciful — Pray for us.\nVirgin most faithful — Pray for us.\nMirror of justice — Pray for us.\nSeat of wisdom — Pray for us.\nCause of our joy — Pray for us.\nSpiritual vessel — Pray for us.\nVessel of honour — Pray for us.\nSingular vessel of devotion — Pray for us.\nMystical rose — Pray for us.\nTower of David — Pray for us.\nTower of ivory — Pray for us.\nHouse of gold — Pray for us.\nArk of the covenant — Pray for us.\nGate of heaven — Pray for us.\nMorning star — Pray for us.\nHealth of the sick — Pray for us.\nRefuge of sinners — Pray for us.\nComfort of the afflicted — Pray for us.\nHelp of Christians — Pray for us.\nQueen of Angels — Pray for us.\nQueen of Patriarchs — Pray for us.\nQueen of Prophets — Pray for us.\nQueen of Apostles — Pray for us.\nQueen of Martyrs — Pray for us.\nQueen of Confessors — Pray for us.\nQueen of Virgins — Pray for us.\nQueen of all Saints — Pray for us.\nQueen conceived without original sin — Pray for us.\nQueen assumed into heaven — Pray for us.\nQueen of the most holy Rosary — Pray for us.\nQueen of peace — Pray for us.\n\nLamb of God, who takest away the sins of the world, spare us, O Lord.\nLamb of God, who takest away the sins of the world, graciously hear us, O Lord.\nLamb of God, who takest away the sins of the world, have mercy on us.\n\n℣. Pray for us, O holy Mother of God.\n℟. That we may be made worthy of the promises of Christ.\n\nLet us pray. Grant, we beseech Thee, O Lord God, that we Thy servants may enjoy perpetual health of mind and body; and by the glorious intercession of blessed Mary, ever Virgin, may be delivered from present sorrow and enjoy eternal gladness. Through Christ our Lord. Amen.","la":"Kyrie, eleison.\nChriste, eleison.\nKyrie, eleison.\nChriste, audi nos.\nChriste, exaudi nos.\n\nPater de cælis, Deus, miserere nobis.\nFili, Redemptor mundi, Deus, miserere nobis.\nSpiritus Sancte, Deus, miserere nobis.\nSancta Trinitas, unus Deus, miserere nobis.\n\nSancta Maria — Ora pro nobis.\nSancta Dei Genetrix — Ora pro nobis.\nSancta Virgo virginum — Ora pro nobis.\nMater Christi — Ora pro nobis.\nMater divinæ gratiæ — Ora pro nobis.\nMater purissima — Ora pro nobis.\nMater castissima — Ora pro nobis.\nMater inviolata — Ora pro nobis.\nMater intemerata — Ora pro nobis.\nMater amabilis — Ora pro nobis.\nMater admirabilis — Ora pro nobis.\nMater boni consilii — Ora pro nobis.\nMater Creatoris — Ora pro nobis.\nMater Salvatoris — Ora pro nobis.\nVirgo prudentissima — Ora pro nobis.\nVirgo veneranda — Ora pro nobis.\nVirgo prædicanda — Ora pro nobis.\nVirgo potens — Ora pro nobis.\nVirgo clemens — Ora pro nobis.\nVirgo fidelis — Ora pro nobis.\nSpeculum iustitiæ — Ora pro nobis.\nSedes sapientiæ — Ora pro nobis.\nCausa nostræ lætitiæ — Ora pro nobis.\nVas spirituale — Ora pro nobis.\nVas honorabile — Ora pro nobis.\nVas insigne devotionis — Ora pro nobis.\nRosa mystica — Ora pro nobis.\nTurris Davidica — Ora pro nobis.\nTurris eburnea — Ora pro nobis.\nDomus aurea — Ora pro nobis.\nFœderis arca — Ora pro nobis.\nIanua cæli — Ora pro nobis.\nStella matutina — Ora pro nobis.\nSalus infirmorum — Ora pro nobis.\nRefugium peccatorum — Ora pro nobis.\nConsolatrix afflictorum — Ora pro nobis.\nAuxilium Christianorum — Ora pro nobis.\nRegina Angelorum — Ora pro nobis.\nRegina Patriarcharum — Ora pro nobis.\nRegina Prophetarum — Ora pro nobis.\nRegina Apostolorum — Ora pro nobis.\nRegina Martyrum — Ora pro nobis.\nRegina Confessorum — Ora pro nobis.\nRegina Virginum — Ora pro nobis.\nRegina Sanctorum omnium — Ora pro nobis.\nRegina sine labe originali concepta — Ora pro nobis.\nRegina in cælum assumpta — Ora pro nobis.\nRegina sacratissimi Rosarii — Ora pro nobis.\nRegina pacis — Ora pro nobis.\n\nAgnus Dei, qui tollis peccata mundi, parce nobis, Domine.\nAgnus Dei, qui tollis peccata mundi, exaudi nos, Domine.\nAgnus Dei, qui tollis peccata mundi, miserere nobis.\n\n℣. Ora pro nobis, sancta Dei Genetrix.\n℟. Ut digni efficiamur promissionibus Christi.\n\nOremus. Concede nos famulos tuos, quæsumus, Domine Deus, perpetua mentis et corporis sanitate gaudere: et gloriosa beatæ Mariæ semper Virginis intercessione, a præsenti liberari tristitia, et æterna perfrui lætitia. Per Christum Dominum nostrum. Amen.","fr":"Seigneur, ayez pitié de nous.\nJésus-Christ, ayez pitié de nous.\nSeigneur, ayez pitié de nous.\nJésus-Christ, écoutez-nous.\nJésus-Christ, exaucez-nous.\n\nPère céleste, qui êtes Dieu, ayez pitié de nous.\nFils, Rédempteur du monde, qui êtes Dieu, ayez pitié de nous.\nEsprit-Saint, qui êtes Dieu, ayez pitié de nous.\nTrinité Sainte, qui êtes un seul Dieu, ayez pitié de nous.\n\nSainte Marie — Priez pour nous.\nSainte Mère de Dieu — Priez pour nous.\nSainte Vierge des vierges — Priez pour nous.\nMère du Christ — Priez pour nous.\nMère de la divine grâce — Priez pour nous.\nMère très pure — Priez pour nous.\nMère très chaste — Priez pour nous.\nMère toujours vierge — Priez pour nous.\nMère sans tache — Priez pour nous.\nMère très aimable — Priez pour nous.\nMère admirable — Priez pour nous.\nMère du bon conseil — Priez pour nous.\nMère du Créateur — Priez pour nous.\nMère du Sauveur — Priez pour nous.\nVierge très prudente — Priez pour nous.\nVierge vénérable — Priez pour nous.\nVierge digne de louange — Priez pour nous.\nVierge puissante — Priez pour nous.\nVierge clémente — Priez pour nous.\nVierge fidèle — Priez pour nous.\nMiroir de justice — Priez pour nous.\nSiège de la sagesse — Priez pour nous.\nCause de notre joie — Priez pour nous.\nVase spirituel — Priez pour nous.\nVase d’honneur — Priez pour nous.\nVase insigne de dévotion — Priez pour nous.\nRose mystique — Priez pour nous.\nTour de David — Priez pour nous.\nTour d’ivoire — Priez pour nous.\nMaison d’or — Priez pour nous.\nArche d’alliance — Priez pour nous.\nPorte du ciel — Priez pour nous.\nÉtoile du matin — Priez pour nous.\nSalut des infirmes — Priez pour nous.\nRefuge des pécheurs — Priez pour nous.\nConsolatrice des affligés — Priez pour nous.\nSecours des chrétiens — Priez pour nous.\nReine des anges — Priez pour nous.\nReine des patriarches — Priez pour nous.\nReine des prophètes — Priez pour nous.\nReine des apôtres — Priez pour nous.\nReine des martyrs — Priez pour nous.\nReine des confesseurs — Priez pour nous.\nReine des vierges — Priez pour nous.\nReine de tous les saints — Priez pour nous.\nReine conçue sans le péché originel — Priez pour nous.\nReine élevée au ciel — Priez pour nous.\nReine du très saint Rosaire — Priez pour nous.\nReine de la paix — Priez pour nous.\n\nAgneau de Dieu, qui effacez les péchés du monde, pardonnez-nous, Seigneur.\nAgneau de Dieu, qui effacez les péchés du monde, exaucez-nous, Seigneur.\nAgneau de Dieu, qui effacez les péchés du monde, ayez pitié de nous.\n\n℣. Priez pour nous, sainte Mère de Dieu.\n℟. Afin que nous devenions dignes des promesses du Christ.\n\nPrions. Accordez à vos serviteurs, nous vous en prions, Seigneur notre Dieu, de jouir toujours de la santé de l’âme et du corps; et, par la glorieuse intercession de la bienheureuse Marie toujours Vierge, d’être délivrés de la tristesse présente et de jouir de la joie éternelle. Par Jésus-Christ Notre-Seigneur. Ainsi soit-il."},"litany_loreto_current":{"id":"litany_loreto_current","title":"Litany of Loreto · current invocations","titleFr":"Litanies de Lorette · invocations actuelles","category":"marian","source":"Holy See · current Litany of Loreto","sourceUrl":"https://www.vatican.va/special/rosary/documents/litanie-lauretane_en.html","note":"Later invocations are shown separately so the older TLM-era form is not silently modernized.","en":"Lord, have mercy on us.\nChrist, have mercy on us.\nLord, have mercy on us.\nChrist, hear us.\nChrist, graciously hear us.\n\nGod the Father of Heaven, have mercy on us.\nGod the Son, Redeemer of the world, have mercy on us.\nGod the Holy Spirit, have mercy on us.\nHoly Trinity, one God, have mercy on us.\n\nHoly Mary — Pray for us.\nHoly Mother of God — Pray for us.\nHoly Virgin of virgins — Pray for us.\nMother of Christ — Pray for us.\nMother of the Church — Pray for us.\nMother of mercy — Pray for us.\nMother of divine grace — Pray for us.\nMother of hope — Pray for us.\nMother most pure — Pray for us.\nMother most chaste — Pray for us.\nMother inviolate — Pray for us.\nMother undefiled — Pray for us.\nMother most amiable — Pray for us.\nMother admirable — Pray for us.\nMother of good counsel — Pray for us.\nMother of our Creator — Pray for us.\nMother of our Saviour — Pray for us.\nVirgin most prudent — Pray for us.\nVirgin most venerable — Pray for us.\nVirgin most renowned — Pray for us.\nVirgin most powerful — Pray for us.\nVirgin most merciful — Pray for us.\nVirgin most faithful — Pray for us.\nMirror of justice — Pray for us.\nSeat of wisdom — Pray for us.\nCause of our joy — Pray for us.\nSpiritual vessel — Pray for us.\nVessel of honour — Pray for us.\nSingular vessel of devotion — Pray for us.\nMystical rose — Pray for us.\nTower of David — Pray for us.\nTower of ivory — Pray for us.\nHouse of gold — Pray for us.\nArk of the covenant — Pray for us.\nGate of heaven — Pray for us.\nMorning star — Pray for us.\nHealth of the sick — Pray for us.\nRefuge of sinners — Pray for us.\nSolace of migrants — Pray for us.\nComfort of the afflicted — Pray for us.\nHelp of Christians — Pray for us.\nQueen of Angels — Pray for us.\nQueen of Patriarchs — Pray for us.\nQueen of Prophets — Pray for us.\nQueen of Apostles — Pray for us.\nQueen of Martyrs — Pray for us.\nQueen of Confessors — Pray for us.\nQueen of Virgins — Pray for us.\nQueen of all Saints — Pray for us.\nQueen conceived without original sin — Pray for us.\nQueen assumed into heaven — Pray for us.\nQueen of the most holy Rosary — Pray for us.\nQueen of families — Pray for us.\nQueen of peace — Pray for us.\n\nLamb of God, who takest away the sins of the world, spare us, O Lord.\nLamb of God, who takest away the sins of the world, graciously hear us, O Lord.\nLamb of God, who takest away the sins of the world, have mercy on us.\n\n℣. Pray for us, O holy Mother of God.\n℟. That we may be made worthy of the promises of Christ.\n\nLet us pray. Grant, we beseech Thee, O Lord God, that we Thy servants may enjoy perpetual health of mind and body; and by the glorious intercession of blessed Mary, ever Virgin, may be delivered from present sorrow and enjoy eternal gladness. Through Christ our Lord. Amen.","la":"Kyrie, eleison.\nChriste, eleison.\nKyrie, eleison.\nChriste, audi nos.\nChriste, exaudi nos.\n\nPater de cælis, Deus, miserere nobis.\nFili, Redemptor mundi, Deus, miserere nobis.\nSpiritus Sancte, Deus, miserere nobis.\nSancta Trinitas, unus Deus, miserere nobis.\n\nSancta Maria — Ora pro nobis.\nSancta Dei Genetrix — Ora pro nobis.\nSancta Virgo virginum — Ora pro nobis.\nMater Christi — Ora pro nobis.\nMater Ecclesiæ — Ora pro nobis.\nMater misericordiæ — Ora pro nobis.\nMater divinæ gratiæ — Ora pro nobis.\nMater spei — Ora pro nobis.\nMater purissima — Ora pro nobis.\nMater castissima — Ora pro nobis.\nMater inviolata — Ora pro nobis.\nMater intemerata — Ora pro nobis.\nMater amabilis — Ora pro nobis.\nMater admirabilis — Ora pro nobis.\nMater boni consilii — Ora pro nobis.\nMater Creatoris — Ora pro nobis.\nMater Salvatoris — Ora pro nobis.\nVirgo prudentissima — Ora pro nobis.\nVirgo veneranda — Ora pro nobis.\nVirgo prædicanda — Ora pro nobis.\nVirgo potens — Ora pro nobis.\nVirgo clemens — Ora pro nobis.\nVirgo fidelis — Ora pro nobis.\nSpeculum iustitiæ — Ora pro nobis.\nSedes sapientiæ — Ora pro nobis.\nCausa nostræ lætitiæ — Ora pro nobis.\nVas spirituale — Ora pro nobis.\nVas honorabile — Ora pro nobis.\nVas insigne devotionis — Ora pro nobis.\nRosa mystica — Ora pro nobis.\nTurris Davidica — Ora pro nobis.\nTurris eburnea — Ora pro nobis.\nDomus aurea — Ora pro nobis.\nFœderis arca — Ora pro nobis.\nIanua cæli — Ora pro nobis.\nStella matutina — Ora pro nobis.\nSalus infirmorum — Ora pro nobis.\nRefugium peccatorum — Ora pro nobis.\nSolacium migrantium — Ora pro nobis.\nConsolatrix afflictorum — Ora pro nobis.\nAuxilium Christianorum — Ora pro nobis.\nRegina Angelorum — Ora pro nobis.\nRegina Patriarcharum — Ora pro nobis.\nRegina Prophetarum — Ora pro nobis.\nRegina Apostolorum — Ora pro nobis.\nRegina Martyrum — Ora pro nobis.\nRegina Confessorum — Ora pro nobis.\nRegina Virginum — Ora pro nobis.\nRegina Sanctorum omnium — Ora pro nobis.\nRegina sine labe originali concepta — Ora pro nobis.\nRegina in cælum assumpta — Ora pro nobis.\nRegina sacratissimi Rosarii — Ora pro nobis.\nRegina familiæ — Ora pro nobis.\nRegina pacis — Ora pro nobis.\n\nAgnus Dei, qui tollis peccata mundi, parce nobis, Domine.\nAgnus Dei, qui tollis peccata mundi, exaudi nos, Domine.\nAgnus Dei, qui tollis peccata mundi, miserere nobis.\n\n℣. Ora pro nobis, sancta Dei Genetrix.\n℟. Ut digni efficiamur promissionibus Christi.\n\nOremus. Concede nos famulos tuos, quæsumus, Domine Deus, perpetua mentis et corporis sanitate gaudere: et gloriosa beatæ Mariæ semper Virginis intercessione, a præsenti liberari tristitia, et æterna perfrui lætitia. Per Christum Dominum nostrum. Amen.","fr":"Seigneur, ayez pitié de nous.\nJésus-Christ, ayez pitié de nous.\nSeigneur, ayez pitié de nous.\nJésus-Christ, écoutez-nous.\nJésus-Christ, exaucez-nous.\n\nPère céleste, qui êtes Dieu, ayez pitié de nous.\nFils, Rédempteur du monde, qui êtes Dieu, ayez pitié de nous.\nEsprit-Saint, qui êtes Dieu, ayez pitié de nous.\nTrinité Sainte, qui êtes un seul Dieu, ayez pitié de nous.\n\nSainte Marie — Priez pour nous.\nSainte Mère de Dieu — Priez pour nous.\nSainte Vierge des vierges — Priez pour nous.\nMère du Christ — Priez pour nous.\nMère de l’Église — Priez pour nous.\nMère de miséricorde — Priez pour nous.\nMère de la divine grâce — Priez pour nous.\nMère de l’espérance — Priez pour nous.\nMère très pure — Priez pour nous.\nMère très chaste — Priez pour nous.\nMère toujours vierge — Priez pour nous.\nMère sans tache — Priez pour nous.\nMère très aimable — Priez pour nous.\nMère admirable — Priez pour nous.\nMère du bon conseil — Priez pour nous.\nMère du Créateur — Priez pour nous.\nMère du Sauveur — Priez pour nous.\nVierge très prudente — Priez pour nous.\nVierge vénérable — Priez pour nous.\nVierge digne de louange — Priez pour nous.\nVierge puissante — Priez pour nous.\nVierge clémente — Priez pour nous.\nVierge fidèle — Priez pour nous.\nMiroir de justice — Priez pour nous.\nSiège de la sagesse — Priez pour nous.\nCause de notre joie — Priez pour nous.\nVase spirituel — Priez pour nous.\nVase d’honneur — Priez pour nous.\nVase insigne de dévotion — Priez pour nous.\nRose mystique — Priez pour nous.\nTour de David — Priez pour nous.\nTour d’ivoire — Priez pour nous.\nMaison d’or — Priez pour nous.\nArche d’alliance — Priez pour nous.\nPorte du ciel — Priez pour nous.\nÉtoile du matin — Priez pour nous.\nSalut des infirmes — Priez pour nous.\nRefuge des pécheurs — Priez pour nous.\nRéconfort des migrants — Priez pour nous.\nConsolatrice des affligés — Priez pour nous.\nSecours des chrétiens — Priez pour nous.\nReine des anges — Priez pour nous.\nReine des patriarches — Priez pour nous.\nReine des prophètes — Priez pour nous.\nReine des apôtres — Priez pour nous.\nReine des martyrs — Priez pour nous.\nReine des confesseurs — Priez pour nous.\nReine des vierges — Priez pour nous.\nReine de tous les saints — Priez pour nous.\nReine conçue sans le péché originel — Priez pour nous.\nReine élevée au ciel — Priez pour nous.\nReine du très saint Rosaire — Priez pour nous.\nReine des familles — Priez pour nous.\nReine de la paix — Priez pour nous.\n\nAgneau de Dieu, qui effacez les péchés du monde, pardonnez-nous, Seigneur.\nAgneau de Dieu, qui effacez les péchés du monde, exaucez-nous, Seigneur.\nAgneau de Dieu, qui effacez les péchés du monde, ayez pitié de nous.\n\n℣. Priez pour nous, sainte Mère de Dieu.\n℟. Afin que nous devenions dignes des promesses du Christ.\n\nPrions. Accordez à vos serviteurs, nous vous en prions, Seigneur notre Dieu, de jouir toujours de la santé de l’âme et du corps; et, par la glorieuse intercession de la bienheureuse Marie toujours Vierge, d’être délivrés de la tristesse présente et de jouir de la joie éternelle. Par Jésus-Christ Notre-Seigneur. Ainsi soit-il."}},"categories":{"essentials":{"en":"Essential prayers","fr":"Prières essentielles"},"massdev":{"en":"Traditional Mass devotions","fr":"Dévotions traditionnelles autour de la Messe"},"marian":{"en":"Our Lady","fr":"Notre-Dame"},"eucharistic":{"en":"Eucharistic devotion","fr":"Dévotion eucharistique"},"saints":{"en":"Saints, Church & protection","fr":"Saints, Église et protection"},"holyghost":{"en":"Holy Ghost","fr":"Saint-Esprit"},"hearts":{"en":"Sacred Heart & reparation","fr":"Sacré-Cœur et réparation"},"canticles":{"en":"Biblical canticles","fr":"Cantiques bibliques"},"dead":{"en":"Holy Souls & the dead","fr":"Âmes du purgatoire et défunts"}},"mysteries":{"joyful":["The Annunciation","The Visitation","The Nativity","The Presentation","The Finding in the Temple"],"luminous":["The Baptism of the Lord","The Wedding at Cana","The Proclamation of the Kingdom","The Transfiguration","The Institution of the Eucharist"],"sorrowful":["The Agony in the Garden","The Scourging at the Pillar","The Crowning with Thorns","The Carrying of the Cross","The Crucifixion"],"glorious":["The Resurrection","The Ascension","The Descent of the Holy Ghost","The Assumption","The Coronation of Our Lady"]},"rosaryPrayers":{"en":{"sign":["Sign of the Cross","In the name of the Father, and of the Son, and of the Holy Spirit. Amen."],"credo":["Apostles’ Creed","I believe in God, the Father almighty, Creator of heaven and earth; and in Jesus Christ, His only Son, our Lord, Who was conceived by the Holy Spirit, born of the Virgin Mary, suffered under Pontius Pilate, was crucified, died and was buried; He descended into hell; on the third day He rose again from the dead; He ascended into heaven, and is seated at the right hand of God the Father almighty; from there He shall come to judge the living and the dead. I believe in the Holy Spirit, the holy Catholic Church, the communion of saints, the forgiveness of sins, the resurrection of the body, and life everlasting. Amen."],"pater":["Our Father","Our Father, Who art in heaven, hallowed be Thy name; Thy kingdom come; Thy will be done on earth as it is in heaven. Give us this day our daily bread; and forgive us our trespasses, as we forgive those who trespass against us; and lead us not into temptation, but deliver us from evil. Amen."],"ave":["Hail Mary","Hail Mary, full of grace, the Lord is with thee; blessed art thou among women, and blessed is the fruit of thy womb, Jesus. Holy Mary, Mother of God, pray for us sinners, now and at the hour of our death. Amen."],"gloria":["Glory Be","Glory be to the Father, and to the Son, and to the Holy Spirit. As it was in the beginning, is now, and ever shall be, world without end. Amen."],"fatima":["Fatima Prayer","O my Jesus, forgive us our sins, save us from the fires of hell; lead all souls to Heaven, especially those most in need of Thy mercy."]},"la":{"sign":["Signum Crucis","In nomine Patris, et Filii, et Spiritus Sancti. Amen."],"credo":["Symbolum Apostolorum","Credo in Deum Patrem omnipotentem, Creatorem cæli et terræ. Et in Iesum Christum, Filium eius unicum, Dominum nostrum: qui conceptus est de Spiritu Sancto, natus ex Maria Virgine, passus sub Pontio Pilato, crucifixus, mortuus, et sepultus; descendit ad inferos; tertia die resurrexit a mortuis; ascendit ad cælos; sedet ad dexteram Dei Patris omnipotentis; inde venturus est iudicare vivos et mortuos. Credo in Spiritum Sanctum, sanctam Ecclesiam catholicam, Sanctorum communionem, remissionem peccatorum, carnis resurrectionem, vitam æternam. Amen."],"pater":["Pater Noster","Pater noster, qui es in cælis, sanctificetur nomen tuum; adveniat regnum tuum; fiat voluntas tua, sicut in cælo et in terra. Panem nostrum quotidianum da nobis hodie; et dimitte nobis debita nostra, sicut et nos dimittimus debitoribus nostris; et ne nos inducas in tentationem, sed libera nos a malo. Amen."],"ave":["Ave Maria","Ave Maria, gratia plena, Dominus tecum; benedicta tu in mulieribus, et benedictus fructus ventris tui, Iesus. Sancta Maria, Mater Dei, ora pro nobis peccatoribus, nunc et in hora mortis nostræ. Amen."],"gloria":["Gloria Patri","Gloria Patri, et Filio, et Spiritui Sancto. Sicut erat in principio, et nunc, et semper, et in sæcula sæculorum. Amen."],"fatima":["Oratio Fatimæ","O mi Iesu, dimitte nobis debita nostra, libera nos ab igne inferni, conduc in cælum omnes animas, præsertim eas quæ misericordiæ tuæ maxime indigent."]},"fr":{"sign":["Signe de la Croix","Au nom du Père, et du Fils, et du Saint-Esprit. Amen."],"credo":["Symbole des Apôtres","Je crois en Dieu, le Père tout-puissant, Créateur du ciel et de la terre; et en Jésus-Christ, son Fils unique, notre Seigneur, qui a été conçu du Saint-Esprit, est né de la Vierge Marie, a souffert sous Ponce Pilate, a été crucifié, est mort et a été enseveli, est descendu aux enfers; le troisième jour est ressuscité des morts, est monté aux cieux, est assis à la droite de Dieu le Père tout-puissant, d’où il viendra juger les vivants et les morts. Je crois au Saint-Esprit, à la sainte Église catholique, à la communion des saints, à la rémission des péchés, à la résurrection de la chair et à la vie éternelle. Ainsi soit-il."],"pater":["Notre Père","Notre Père, qui êtes aux cieux, que votre nom soit sanctifié; que votre règne arrive; que votre volonté soit faite sur la terre comme au ciel. Donnez-nous aujourd’hui notre pain de chaque jour; pardonnez-nous nos offenses, comme nous pardonnons à ceux qui nous ont offensés; et ne nous laissez pas succomber à la tentation, mais délivrez-nous du mal. Amen."],"ave":["Je vous salue Marie","Je vous salue, Marie, pleine de grâce, le Seigneur est avec vous; vous êtes bénie entre toutes les femmes, et Jésus, le fruit de vos entrailles, est béni. Sainte Marie, Mère de Dieu, priez pour nous, pauvres pécheurs, maintenant et à l’heure de notre mort. Amen."],"gloria":["Gloire au Père","Gloire au Père, au Fils et au Saint-Esprit, comme il était au commencement, maintenant et toujours, et dans les siècles des siècles. Amen."],"fatima":["Prière de Fatima","Ô mon Jésus, pardonnez-nous nos péchés, préservez-nous du feu de l’enfer, conduisez au ciel toutes les âmes, surtout celles qui ont le plus besoin de votre miséricorde."]}},"salve":{"en":"Hail, holy Queen, Mother of mercy, our life, our sweetness and our hope. To thee do we cry, poor banished children of Eve; to thee do we send up our sighs, mourning and weeping in this valley of tears. Turn then, most gracious Advocate, thine eyes of mercy toward us; and after this our exile show unto us the blessed fruit of thy womb, Jesus. O clement, O loving, O sweet Virgin Mary.\n\nV. Pray for us, O holy Mother of God.\nR. That we may be made worthy of the promises of Christ.","la":"Salve, Regina, Mater misericordiæ; vita, dulcedo et spes nostra, salve. Ad te clamamus, exsules filii Hevæ. Ad te suspiramus, gementes et flentes in hac lacrimarum valle. Eia ergo, advocata nostra, illos tuos misericordes oculos ad nos converte. Et Iesum, benedictum fructum ventris tui, nobis post hoc exsilium ostende. O clemens, o pia, o dulcis Virgo Maria.\n\nV. Ora pro nobis, sancta Dei Genetrix.\nR. Ut digni efficiamur promissionibus Christi.","fr":"Salut, ô Reine, Mère de miséricorde, notre vie, notre douceur et notre espérance, salut. Enfants d’Ève exilés, nous crions vers vous. Vers vous nous soupirons, gémissant et pleurant dans cette vallée de larmes. Ô vous, notre avocate, tournez vers nous vos regards miséricordieux. Et après cet exil, montrez-nous Jésus, le fruit béni de vos entrailles. Ô clémente, ô charitable, ô douce Vierge Marie.\n\nV. Priez pour nous, sainte Mère de Dieu.\nR. Afin que nous devenions dignes des promesses du Christ."},"rosaryCollect":{"en":"Let us pray. O God, whose only-begotten Son, by His life, death and resurrection, has purchased for us the rewards of eternal life: grant, we beseech Thee, that meditating upon these mysteries of the most holy Rosary of the Blessed Virgin Mary, we may imitate what they contain and obtain what they promise. Through the same Christ our Lord. Amen.","la":"Oremus. Deus, cuius Unigenitus per vitam, mortem et resurrectionem suam nobis salutis æternæ præmia comparavit: concede, quæsumus; ut hæc mysteria sacratissimo beatæ Mariæ Virginis Rosario recolentes, et imitemur quod continent, et quod promittunt assequamur. Per eundem Christum Dominum nostrum. Amen.","fr":"Prions. Ô Dieu, dont le Fils unique nous a acquis, par sa vie, sa mort et sa résurrection, les récompenses de la vie éternelle, accordez-nous, nous vous en supplions, qu’en méditant ces mystères du très saint Rosaire de la bienheureuse Vierge Marie, nous imitions ce qu’ils contiennent et obtenions ce qu’ils promettent. Par le même Jésus-Christ Notre-Seigneur. Ainsi soit-il."},"angelus":{"en":"℣ The Angel of the Lord declared unto Mary.\n℟ And she conceived of the Holy Spirit.\nHail Mary, full of grace, the Lord is with thee; blessed art thou among women, and blessed is the fruit of thy womb, Jesus. Holy Mary, Mother of God, pray for us sinners, now and at the hour of our death. Amen.\n\n℣ Behold the handmaid of the Lord.\n℟ Be it done unto me according to thy word.\nHail Mary, full of grace, the Lord is with thee; blessed art thou among women, and blessed is the fruit of thy womb, Jesus. Holy Mary, Mother of God, pray for us sinners, now and at the hour of our death. Amen.\n\n℣ And the Word was made flesh.\n℟ And dwelt among us.\nHail Mary, full of grace, the Lord is with thee; blessed art thou among women, and blessed is the fruit of thy womb, Jesus. Holy Mary, Mother of God, pray for us sinners, now and at the hour of our death. Amen.\n\n℣ Pray for us, O holy Mother of God.\n℟ That we may be made worthy of the promises of Christ.\n\nLet us pray: Pour forth, we beseech thee, O Lord, thy grace into our hearts; that we, to whom the Incarnation of Christ, thy Son, was made known by the message of an angel, may by his Passion and Cross be brought to the glory of his Resurrection. Through the same Christ our Lord. Amen.","la":"V. Angelus Domini nuntiavit Mariae.\nR. Et concepit de Spiritu Sancto.\n\nAve Maria, gratia plena, Dominus tecum; benedicta tu in mulieribus, et benedictus fructus ventris tui, Iesus. Sancta Maria, Mater Dei, ora pro nobis peccatoribus, nunc et in hora mortis nostræ. Amen.\n\nV. Ecce ancilla Domini.\nR. Fiat mihi secundum verbum tuum.\n\nAve Maria, gratia plena, Dominus tecum; benedicta tu in mulieribus, et benedictus fructus ventris tui, Iesus. Sancta Maria, Mater Dei, ora pro nobis peccatoribus, nunc et in hora mortis nostræ. Amen.\n\nV. Et Verbum caro factum est.\nR. Et habitavit in nobis.\n\nAve Maria, gratia plena, Dominus tecum; benedicta tu in mulieribus, et benedictus fructus ventris tui, Iesus. Sancta Maria, Mater Dei, ora pro nobis peccatoribus, nunc et in hora mortis nostræ. Amen.\n\nV. Ora pro nobis, sancta Dei Genetrix.\nR. Ut digni efficiamur promissionibus Christi.\n\nOremus. Gratiam tuam, quaesumus, Domine, mentibus nostris infunde; ut qui, Angelo nuntiante, Christi Filii tui incarnationem cognovimus, per passionem eius et crucem ad resurrectionis gloriam perducamur. Per eundem Christum Dominum nostrum. Amen.","fr":"V. L’Ange du Seigneur annonça à Marie.\nR. Et elle conçut du Saint-Esprit.\n\nJe vous salue, Marie, pleine de grâce; le Seigneur est avec vous; vous êtes bénie entre toutes les femmes, et Jésus, le fruit de vos entrailles, est béni. Sainte Marie, Mère de Dieu, priez pour nous, pauvres pécheurs, maintenant et à l’heure de notre mort. Ainsi soit-il.\n\nV. Voici la servante du Seigneur.\nR. Qu’il me soit fait selon votre parole.\n\nJe vous salue, Marie, pleine de grâce; le Seigneur est avec vous; vous êtes bénie entre toutes les femmes, et Jésus, le fruit de vos entrailles, est béni. Sainte Marie, Mère de Dieu, priez pour nous, pauvres pécheurs, maintenant et à l’heure de notre mort. Ainsi soit-il.\n\nV. Et le Verbe s’est fait chair.\nR. Et il a habité parmi nous.\n\nJe vous salue, Marie, pleine de grâce; le Seigneur est avec vous; vous êtes bénie entre toutes les femmes, et Jésus, le fruit de vos entrailles, est béni. Sainte Marie, Mère de Dieu, priez pour nous, pauvres pécheurs, maintenant et à l’heure de notre mort. Ainsi soit-il.\n\nV. Priez pour nous, sainte Mère de Dieu.\nR. Afin que nous soyons rendus dignes des promesses du Christ.\n\nPrions. Que ta grâce, Seigneur, se répande en nos cœurs; par le message de l’ange, tu nous as fait connaître l’Incarnation de ton Fils bien-aimé; conduis-nous, par sa Passion et par sa Croix, jusqu’à la gloire de la Résurrection. Par le Christ, notre Seigneur. Amen."},"angelusAppendix":{"en":"Glory be to the Father, and to the Son, and to the Holy Spirit. As it was in the beginning, is now, and ever shall be, world without end. Amen. (three times)\n\n℣. May the souls of the faithful departed, through the mercy of God, rest in peace.\n℟. Amen.\n\n℣. May the divine assistance remain always with us.\n℟. Amen.","la":"Gloria Patri, et Filio, et Spiritui Sancto. Sicut erat in principio, et nunc, et semper, et in sæcula sæculorum. Amen. (ter)\n\n℣. Fidelium animæ per misericordiam Dei requiescant in pace.\n℟. Amen.\n\n℣. Divinum auxilium maneat semper nobiscum.\n℟. Amen.","fr":"Gloire au Père, au Fils et au Saint-Esprit, comme il était au commencement, maintenant et toujours, et dans les siècles des siècles. Ainsi soit-il. (trois fois)\n\n℣. Que les âmes des fidèles défunts reposent en paix par la miséricorde de Dieu.\n℟. Ainsi soit-il.\n\n℣. Que le secours divin demeure toujours avec nous.\n℟. Ainsi soit-il."},"regina":{"en":"℣. Queen of heaven, rejoice, alleluia.\n℟. For He whom thou didst merit to bear, alleluia.\n℣. Has risen, as He said, alleluia.\n℟. Pray for us to God, alleluia.\n\n℣. Rejoice and be glad, O Virgin Mary, alleluia.\n℟. For the Lord is truly risen, alleluia.\n\nLet us pray. O God, who by the resurrection of Thy Son, our Lord Jesus Christ, hast vouchsafed to give joy to the whole world: grant, we beseech Thee, that through the intercession of the Virgin Mary, His Mother, we may obtain the joys of everlasting life. Through the same Christ our Lord. Amen.","la":"℣. Regina cæli, lætare, alleluia.\n℟. Quia quem meruisti portare, alleluia.\n℣. Resurrexit, sicut dixit, alleluia.\n℟. Ora pro nobis Deum, alleluia.\n\n℣. Gaude et lætare, Virgo Maria, alleluia.\n℟. Quia surrexit Dominus vere, alleluia.\n\nOremus. Deus, qui per resurrectionem Filii tui, Domini nostri Iesu Christi, mundum lætificare dignatus es: præsta, quæsumus, ut per eius Genetricem Virginem Mariam perpetuæ capiamus gaudia vitæ. Per eundem Christum Dominum nostrum. Amen.","fr":"℣. Reine du ciel, réjouissez-vous, alléluia.\n℟. Car celui que vous avez mérité de porter, alléluia.\n℣. Est ressuscité comme il l’avait dit, alléluia.\n℟. Priez Dieu pour nous, alléluia.\n\n℣. Réjouissez-vous et soyez dans l’allégresse, Vierge Marie, alléluia.\n℟. Parce que le Seigneur est vraiment ressuscité, alléluia.\n\nPrions. Ô Dieu, qui avez daigné réjouir le monde par la résurrection de votre Fils, Notre-Seigneur Jésus-Christ, faites, nous vous en supplions, que par sa Mère, la Vierge Marie, nous obtenions les joies de la vie éternelle. Par le même Jésus-Christ Notre-Seigneur. Ainsi soit-il."},"stationTitles":{"en":["Jesus Is Condemned to Death","Jesus Is Made to Bear His Cross","Jesus Falls the First Time","Jesus Meets His Blessed Mother","Simon of Cyrene Helps Jesus Carry His Cross","Veronica Wipes the Face of Jesus","Jesus Falls the Second Time","Jesus Consoles the Women of Jerusalem","Jesus Falls the Third Time","Jesus Is Stripped of His Garments","Jesus Is Nailed to the Cross","Jesus Dies on the Cross","Jesus Is Taken Down from the Cross","Jesus Is Laid in the Sepulchre"],"la":["Iesus condemnatur ad mortem","Iesus baiulat crucem","Iesus primum cadit sub cruce","Iesus occurrit Matri suae","Simon Cyrenaeus adiuvat Iesum crucem portare","Veronica faciem Iesu abstergit","Iesus iterum cadit sub cruce","Iesus alloquitur mulieres Ierusalem","Iesus tertium cadit sub cruce","Iesus vestibus exuitur","Iesus cruci affigitur","Iesus moritur in cruce","Iesus de cruce deponitur","Iesus in sepulcro ponitur"],"fr":["Jésus est condamné à mort","Jésus est chargé de sa croix","Jésus tombe pour la première fois","Jésus rencontre sa très sainte Mère","Simon de Cyrène aide Jésus à porter sa croix","Véronique essuie le visage de Jésus","Jésus tombe pour la deuxième fois","Jésus console les filles de Jérusalem","Jésus tombe pour la troisième fois","Jésus est dépouillé de ses vêtements","Jésus est cloué à la croix","Jésus meurt sur la croix","Jésus est descendu de la croix","Jésus est mis au tombeau"]},"stationVR":{"en":["℣. We adore Thee, O Christ, and we bless Thee.","℟. Because by Thy holy Cross Thou hast redeemed the world."],"la":["℣. Adoramus te, Christe, et benedicimus tibi.","℟. Quia per sanctam crucem tuam redemisti mundum."],"fr":["℣. Nous vous adorons, ô Christ, et nous vous bénissons.","℟. Parce que par votre sainte Croix vous avez racheté le monde."]},"stabat":["Stabat Mater dolorosa\niuxta Crucem lacrimosa,\ndum pendebat Filius.","Cuius animam gementem,\ncontristatam et dolentem,\npertransivit gladius.","O quam tristis et afflicta\nfuit illa benedicta,\nMater Unigeniti!","Quae maerebat et dolebat,\npia Mater, dum videbat\nnati poenas inclyti.","Quis est homo qui non fleret,\nMatrem Christi si videret\nin tanto supplicio?","Quis non posset contristari,\nChristi Matrem contemplari\ndolentem cum Filio?","Pro peccatis suae gentis\nvidit Iesum in tormentis,\net flagellis subditum.","Vidit suum dulcem Natum\nmoriendo desolatum,\ndum emisit spiritum.","Eia, Mater, fons amoris,\nme sentire vim doloris\nfac, ut tecum lugeam.","Fac ut ardeat cor meum\nin amando Christum Deum,\nut sibi complaceam.","Sancta Mater, istud agas,\nCrucifixi fige plagas\ncordi meo valide.","Tui Nati vulnerati,\ntam dignati pro me pati,\npoenas mecum divide.","Fac me tecum pie flere,\nCrucifixo condolere,\ndonec ego vixero."],"alphonsus":{"en":[{"consider":"Consider how Jesus, after having been scourged and crowned with thorns, was unjustly condemned by Pilate to die on the Cross.","prayer":"My adorable Jesus, it was not Pilate; no, it was my sins that condemned Thee to die. I beseech Thee, by the merits of this sorrowful journey, to assist my soul in its journey toward eternity. I love Thee, my beloved Jesus; I love Thee more than myself; I repent with my whole heart of having offended Thee. Never permit me to separate myself from Thee again. Grant that I may love Thee always, and then do with me what Thou wilt."},{"consider":"Consider how Jesus, in making this journey with the Cross on His shoulders, thought of us, and offered for us to His Father the death He was about to undergo.","prayer":"My most beloved Jesus, I embrace all the tribulations Thou hast destined for me until death. I beseech Thee, by the merits of the pain Thou didst suffer in carrying Thy Cross, to give me the necessary help to carry mine with perfect patience and resignation. I love Thee, Jesus my love; I love Thee more than myself; I repent of having offended Thee. Never permit me to separate myself from Thee again. Grant that I may love Thee always, and then do with me what Thou wilt."},{"consider":"Consider this first fall of Jesus under His Cross. His flesh was torn by the scourges, His head crowned with thorns, and He had lost a great quantity of blood. He was so weakened that He could scarcely walk, and yet He had to carry this great load upon His shoulders. The soldiers struck Him rudely, and thus He fell several times in His journey.","prayer":"My beloved Jesus, it is not the weight of the Cross, but my sins which have made Thee suffer so much pain. By the merits of this first fall, deliver me from the misfortune of falling into mortal sin. I love Thee, Jesus, with my whole heart; I repent of having offended Thee. Never permit me to offend Thee again. Grant that I may love Thee always, and then do with me what Thou wilt."},{"consider":"Consider the meeting of the Son and the Mother which took place on this journey. Jesus and Mary looked at each other, and their looks became as so many arrows to wound those hearts which loved each other so tenderly.","prayer":"My most loving Jesus, by the sorrow that Thou didst experience in this meeting, grant me the grace of a truly devoted love for Thy most holy Mother. And thou, my Queen, who wast overwhelmed with sorrow, obtain for me, by thy intercession, a continual and tender remembrance of the Passion of thy Son. I love Thee, Jesus my love; I repent of having offended Thee. Never permit me to offend Thee again. Grant that I may love Thee always, and then do with me what Thou wilt."},{"consider":"Consider how the Jews, seeing that at each step Jesus, from weakness, was on the point of expiring, and fearing that He would die on the way when they wished Him to die the shameful death of the Cross, constrained Simon the Cyrenian to carry the Cross behind our Lord.","prayer":"My most beloved Jesus, I will not refuse the Cross as the Cyrenian did; I accept it, I embrace it. I accept in particular the death Thou hast destined for me, with all the pains which may accompany it; I unite it to Thy death and offer it to Thee. Thou hast died for love of me. I will die for love of Thee, and to please Thee. Help me by Thy grace. I love Thee, Jesus my love; I repent of having offended Thee. Never permit me to offend Thee again. Grant that I may love Thee always, and then do with me what Thou wilt."},{"consider":"Consider how the holy woman named Veronica, seeing Jesus so afflicted and His face bathed in sweat and blood, presented Him with a towel, with which He wiped His adorable face, leaving on it the impression of His holy countenance.","prayer":"My most beloved Jesus, Thy face was beautiful before, but in this journey it has lost all its beauty, and wounds and blood have disfigured it. Alas! my soul also was once beautiful, when it received Thy grace in Baptism; but I have disfigured it since by my sins. Thou alone, my Redeemer, can restore it to its former beauty. Do this by Thy Passion. I love Thee, Jesus my love; I repent of having offended Thee. Never permit me to offend Thee again. Grant that I may love Thee always, and then do with me what Thou wilt."},{"consider":"Consider the second fall of Jesus under the Cross, a fall which renews the pain of all the wounds of the head and members of our afflicted Lord.","prayer":"My most gentle Jesus, how many times Thou hast pardoned me, and how many times have I fallen again and begun again to offend Thee! By the merits of this new fall, give me the necessary helps to persevere in Thy grace until death. Grant that in all temptations which assail me, I may always commend myself to Thee. I love Thee, Jesus my Love, with my whole heart; I repent of having offended Thee. Never permit me to offend Thee again. Grant that I may love Thee always, and then do with me what Thou wilt."},{"consider":"Consider how those women wept with compassion at seeing Jesus in such a pitiable state, streaming with Blood as He walked along. But Jesus said to them: “Weep not for Me, but for your children.”","prayer":"My Jesus, laden with sorrows, I weep for the offenses I have committed against Thee, because of the pains they have deserved, and still more because of the displeasure they have caused Thee, Who hast loved me so much. It is Thy love more than the fear of hell which causes me to weep for my sins. My Jesus, I love Thee more than myself. I repent of having offended Thee. Never permit me to offend Thee again. Grant that I may love Thee always, and then do with me what Thou wilt."},{"consider":"Consider the third fall of Jesus Christ. His weakness was extreme, and the cruelty of His executioners excessive, who tried to hasten His steps when He had scarcely strength to move.","prayer":"Ah, my outraged Jesus, by the merits of the weakness Thou didst suffer in going to Calvary, give me strength sufficient to conquer all human respect and all my wicked passions, which have led me to despise Thy friendship. I love Thee, Jesus my love, with my whole heart. I repent of having offended Thee. Never permit me to offend Thee again. Grant that I may love Thee always, and then do with me what Thou wilt."},{"consider":"Consider the violence with which the executioners stripped Jesus. His inner garments adhered to His torn flesh, and they dragged them off so roughly that the skin came with them. Compassionate thy Saviour thus cruelly treated.","prayer":"My innocent Jesus, by the merits of the torments Thou hast felt, help me to strip myself of all affection to things of earth, in order that I may place all my love in Thee, Who art so worthy of my love. I love Thee, O Jesus, with my whole heart. I repent of having offended Thee. Never permit me to offend Thee again. Grant that I may love Thee always, and then do with me what Thou wilt."},{"consider":"Consider how Jesus, after being thrown on the Cross, extended His hands and offered to His Eternal Father the sacrifice of His life for our salvation. They fastened Him with nails and then, raising the Cross, left Him to die in anguish.","prayer":"My Jesus, loaded with contempt, nail my heart to Thy feet, that it may ever remain there, to love Thee and never quit Thee again. I love Thee more than myself. I repent of having offended Thee. Never permit me to offend Thee again. Grant that I may love Thee always, and then do with me what Thou wilt."},{"consider":"Consider how thy Jesus, after three hours of agony on the Cross, consumed at length with anguish, abandons Himself to the weight of His Body, bows His Head, and dies.","prayer":"O my dying Jesus, I kiss devoutly the Cross on which Thou didst die for love of me. I have merited by my sins to die a miserable death, but Thy death is my hope. By the merits of Thy death, give me grace to die embracing Thy feet and burning with love for Thee. I yield my soul into Thy hands. I love Thee with my whole heart; I repent of having offended Thee. Never permit me to offend Thee again. Grant that I may love Thee always, and then do with me what Thou wilt."},{"consider":"Consider how, after the death of our Lord, two of His disciples, Joseph and Nicodemus, took Him down from the Cross and placed Him in the arms of His afflicted Mother, who received Him with unutterable tenderness and pressed Him to her bosom.","prayer":"O Mother of Sorrows, for the love of this Son, accept me for thy servant and pray to Him for me. And Thou, my Redeemer, since Thou hast died for me, permit me to love Thee; for I wish but Thee and nothing more. I love Thee, my Jesus, and I repent of having offended Thee. Never permit me to offend Thee again. Grant that I may love Thee always, and then do with me what Thou wilt."},{"consider":"Consider how the disciples carried the Body of Jesus to bury it, accompanied by His holy Mother, who arranged it in the sepulchre with her own hands. They then closed the tomb, and all withdrew.","prayer":"Ah, my buried Jesus, I kiss the stone that encloses Thee. But Thou didst rise again the third day. I beseech Thee by Thy resurrection, make me rise glorious with Thee at the last day, to be always united with Thee in Heaven, to praise Thee and love Thee forever. I love Thee, and I repent of having offended Thee. Never permit me to offend Thee again. Grant that I may love Thee always, and then do with me what Thou wilt."}],"la":[{"consider":"Considera quomodo Iesus Christus, iam flagellatus et spinis coronatus, iniuste tandem a Pilato ad mortem crucis condemnetur.","prayer":"O adorande Iesu, non Pilatus, sed iniqua mea vita te ad mortem condemnavit. Per meritum laboriosissimi huius itineris, quod ad Calvariae montem instituis, precor te, ut me semper in via, qua anima mea in aeternitatem tendit, benigne comiteris. Amo te, o Iesu, mi Amor, magis quam meipsum, et ex intimo corde paenitet me quod tibi displicui. Ne sinas me iterum a te separari. Da mihi perpetuum amorem tui, et dein fac de me quidquid tibi placuerit. Quod tibi placitum est, hoc idem mihi est acceptum."},{"consider":"Considera quomodo Iesus Christus, portans humeris crucem, fuerit inter eundum, memor tui, offerendo pro te aeterno Patri mortem, quam erat obiturus.","prayer":"Amabilissime Iesu, amplector omnes res adversas, quas mihi usque ad obitum tolerandas praefixisti, et, per durum illum, quem in portanda tua cruce pertulisti, laborem, precor te, ut vires mihi subministres, quibus ego quoque crucem meam, aequo ac patienti animo, portare valeam. Amo te, o Iesu, mi Amor, paenitet me quod tibi displicui. Ne sinas me iterum separari a te. Da mihi perpetuum amorem tui, et dein fac de me quidquid tibi placuerit."},{"consider":"Considera primum hunc Iesu Christi sub cruce lapsum. Habebat carnem ex saeva flagellatione multifarie sauciam, caput redimitum spinarum corona; profuderat insuper cruorem in tanta copia, ut vix pedem prae virium defectione movere posset. Et quoniam gravi crucis onere premebatur et immisericorditer a militibus propellebatur, accidit ut pluries inter eundum humi procumberet.","prayer":"O mi Iesu, non est onus crucis, sed peccatorum meorum pondus, quod tantis te afficit doloribus. Rogo te, per primum hunc tuum lapsum, ut ab omni in peccatum me lapsu tuearis. Amo te, o Iesu, ex toto corde meo; paenitet me quod tibi displicui. Ne sinas me iterum in peccatum prolabi. Da mihi perpetuum amorem tui, et dein fac de me quidquid tibi placuerit."},{"consider":"Considera qualis fuerit, in hac via, Filii et Matris occursus. Iesus et Maria se mutuo aspexerunt, mutuique eorum aspectus fuerunt totidem sagittae, quibus amantia eorum pectora transverberabantur.","prayer":"Amantissime Iesu, per acerbum dolorem, quem in hoc occursu expertus es, redde me, precor, sanctissimae Matri tuae vere devotum. Tu vero, perdolens mea Regina, intercede pro me, et obtine mihi talem cruciatum Filii tui memoriam, ut mens mea in pia illorum contemplatione perpetuo detineatur. Amo te, o Iesu, mi Amor; paenitet me quod tibi displicui. Ne sinas me iterum in te peccare. Da mihi perpetuum amorem tui, et dein fac de me quidquid tibi placuerit."},{"consider":"Considera quomodo Iudaei, videntes Iesum ad quemlibet passum animam propemodum prae lassitudine efflantem, et timentes ex altera parte ne, quem crucis supplicio affectum volebant, in via moreretur, compellant Simonem Cyrenaeum ad baiulandam crucem post Dominum.","prayer":"O dulcissime Iesu, nolo sicut Cyrenaeus repudiare crucem; libenter eam amplector in meque recipio, amplector speciatim quam mihi praefiniisti mortem cum omnibus, quos haec secum adductura est, doloribus. Coniungo eam cum morte tua, sicque coniunctam eam in sacrificium tibi offero. Tu amore mei mortuus es; volo ego quoque mori amore tui, ea mente ut rem tibi gratam faciam. Tu vero adiuva me tua gratia. Amo te, o Iesu, mi Amor; paenitet me quod tibi displicui. Ne sinas me iterum tibi displicere. Da mihi perpetuum amorem tui, et dein fac de me quidquid tibi placuerit."},{"consider":"Considera quomodo sancta illa femina Veronica, videns Iesum doloribus confectum eiusque vultum sudore ac sanguine madidum, porrigat ei linteolum in quo ipse, abstersa facie, sacram sui imaginem impressam relinquit.","prayer":"O mi Iesu, formosa erat antea facies tua; verum hac in via non amplius formosa apparet, sed est vulneribus et cruore omnino deformis. Hei mihi! quam formosa quoque erat anima mea, cum gratiam tuam per baptismum recepisset: peccando eam postea deformem reddidi. Tu solus, mi Redemptor, pristinam venustatem ei restituere vales; quod ut facias, per tuae Passionis meritum te precor. Amo te Iesu, mi Amor; paenitet me quod tibi displicui; ne sinas me iterum tibi displicere. Da mihi perpetuum amorem tui, et dein fac de me quidquid tibi placuerit."},{"consider":"Considera alterum Iesu Christi sub cruce lapsum, quo lapsu perdolenti Domino omnes venerandi capitis et totius corporis plagae recrudescunt, omnesque cruciatus renovantur.","prayer":"Mansuetissime Iesu, quam frequenter concessisti mihi veniam! Ego vero in eadem relapsus sum peccata, measque in te offensas renovavi. Per meritum novi huius tui lapsus adiuva me, ut in gratia tua usque ad obitum perseverem. Fac ut in omnibus, quae me invasurae sunt, tentationibus me tibi semper commendem. Amo te ex toto corde meo, o Iesu, mi Amor; paenitet me quod tibi displicui: ne sinas me iterum tibi displicere. Da mihi perpetuum amorem tui, et dein fac de me quidquid tibi placuerit."},{"consider":"Considera quomodo mulieres, videntes Iesum lassitudine exanimatum et cruore inter eundum diffluentem, commiseratione permoveantur, lacrimasque profundant. Ad flentes autem conversus: “Nolite, inquit, flere super me, sed super vos ipsas flete et super filios vestros.”","prayer":"O perdolens Iesu, defleo mea in te peccata ob poenas quidem quibus me dignum reddiderunt, sed maxime ob molestiam quam tibi intulerunt, tibi qui me tantopere amasti. Ad fletum minus infernus quam amor tui me excitat. O mi Iesu, amo te magis quam meipsum; paenitet me quod tibi displicui; ne sinas me iterum tibi displicere. Da mihi perpetuum amorem tui, et dein fac de me quidquid tibi placuerit."},{"consider":"Considera tertium Iesu Christi sub cruce lapsum. Procumbit quia nimia erat eius debilitas, et nimia saevitia carnificum, qui volebant ut gressum acceleraret, dum vix unum gradum facere posset.","prayer":"O inclementer habite Iesu, per meritum illius virium defectionis, qua in via ad Calvarium laborare voluisti, tanto, precor, me vigore conforta, ut nullum amplius ad humana iudicia respectum habeam, ac vitiosam meam naturam edomem: quod utrumque in causa fuit cur tuam olim amicitiam contempserim. Amo te, o Iesu, mi Amor, ex toto corde meo; paenitet me quod tibi displicui: ne sinas me iterum tibi displicere. Da mihi perpetuum amorem tui, et dein fac de me quidquid tibi placuerit."},{"consider":"Considera quam violenter Iesus vestimentis suis spolietur. Cum enim vestis interior arcte carni flagellis dilaniatae adhaereret, carnifices, avellendo vestem, cutem ei quoque avellunt. Subeat te commiseratio Domini tui, eumque sic alloquere.","prayer":"Innocentissime Iesu, per meritum doloris quem inter hanc spoliationem passus es, adiuva me, precor, ut omnem in res creatas affectum exuam, et tota voluntatis meae inclinatione ad te solum convertar, qui meo nimis dignus es amore. Amo te ex toto corde meo; paenitet me quod tibi displicui; ne sinas me iterum tibi displicere. Da mihi perpetuum amorem tui, et dein fac de me quidquid tibi placuerit."},{"consider":"Considera quomodo Iesus in crucem coniciatur, et extensis brachiis, vitam suam in sacrificium pro nostra salute aeterno Patri offerat. Carnifices clavis eum affigunt, dein erigunt crucem, et infami patibulo suffixum saevae morti permittunt.","prayer":"O contemptissime Iesu, affige pedibus tuis cor meum, ut amoris vinculo ligatum semper tecum remaneat, necque amplius a te avellatur. Amo te magis quam meipsum; paenitet me quod tibi displicui: ne permittas me iterum tibi displicere. Da mihi perpetuum amorem tui, et dein fac de me quidquid tibi placuerit."},{"consider":"Considera tuum cruci suffixum Iesum, qui post trium horarum cum morte luctam, doloribus tandem consumptus addicit corpus morti, et inclinato capite emittit spiritum.","prayer":"O mortue Iesu, exosculor, pietatis sensu intime commotus, hanc crucem in qua tu, mei causa, vitae tuae finem implevisti. Ob commissa peccata infelicem mihi mortem promerui; sed mors tua est spes mea. Per mortis tuae merita, concede mihi precor, ut in amplexu pedum tuorum extremum spiritum, tui amore flagrans, aliquando reddam. In manus tuas commendo spiritum meum. Amo te ex toto corde meo; paenitet me quod tibi displicui: ne sinas me iterum tibi displicere. Da mihi perpetuum amorem tui, et dein fac de me quidquid tibi placuerit."},{"consider":"Considera quomodo duo ex Iesu discipulis, Iosephus nempe et Nicodemus, eum exanimatum de cruce tollant et inter brachia perdolentis Matris reponant, quae mortuum Filium peramanter recipit et arcte complectitur.","prayer":"O moerens Mater, per amorem quo Filium tuum amas, accipe me in servum tuum et precare eum pro me. Tu vero, o mi Redemptor, quoniam pro me mortuus es, fac benigne ut amem te; te enim solum volo, nec extra te aliud quidpiam mihi opto. Amo te, o mi Iesu, paenitet me quod tibi displicui: ne sinas me iterum tibi displicere. Da mihi perpetuum amorem tui, et dein fac de me quidquid tibi placuerit."},{"consider":"Considera quomodo discipuli exanimem Redemptorem ad locum sepulturae deferant. Moerens Mater eos comitatur, et propriis manibus corpus Filii sepulturae accommodat. Sepulchrum dein occluditur, et omnes a loco recedunt.","prayer":"O sepulte Iesu, exosculor hunc, qui te recondit, lapidem; sed post triduum ex sepulcro resurges. Per tuam resurrectionem fac me, precor, extremo die gloriosum tecum resurgere, et venire in caelum, ubi tecum semper coniunctus, te laudabo et in aeternum amabo. Amo te, et doleo quod tibi displicui: ne sinas me iterum tibi displicere. Da mihi perpetuum amorem tui, et dein fac de me quidquid tibi placuerit."}],"fr":[{"consider":"Considérez comment Jésus, après avoir été flagellé et couronné d’épines, fut enfin injustement condamné par Pilate à mourir sur la Croix.","prayer":"Ô Jésus adorable, ce n’est pas Pilate, mais mes péchés qui Vous ont condamné à mort. Par les mérites de ce douloureux chemin que Vous entreprenez vers le Calvaire, je Vous supplie d’accompagner mon âme dans le chemin qui la conduit à l’éternité. Je Vous aime, ô Jésus, mon amour, plus que moi-même; je me repens de tout mon cœur de Vous avoir offensé. Ne permettez pas que je me sépare encore de Vous. Donnez-moi de Vous aimer toujours; et ensuite disposez de moi comme il Vous plaira."},{"consider":"Considérez comment Jésus-Christ, portant la Croix sur ses épaules, pensait à nous en chemin, et offrait pour nous à son Père éternel la mort qu’Il allait souffrir.","prayer":"Ô Jésus très aimable, j’embrasse toutes les adversités que Vous m’avez destinées jusqu’à la mort; et, par la douleur que Vous avez endurée en portant votre Croix, je Vous supplie de me donner les forces nécessaires pour porter la mienne avec une parfaite patience et résignation. Je Vous aime, Jésus mon amour; je me repens de Vous avoir offensé. Ne permettez pas que je me sépare encore de Vous. Donnez-moi de Vous aimer toujours; et ensuite disposez de moi comme il Vous plaira."},{"consider":"Considérez cette première chute de Jésus sous le poids de la Croix. Sa chair était déchirée par la flagellation, sa tête couronnée d’épines, et Il avait répandu tant de sang qu’Il pouvait à peine marcher. Cependant Il devait porter sur ses épaules ce pesant fardeau; les soldats Le poussaient sans pitié, et Il tomba ainsi plusieurs fois sur le chemin.","prayer":"Ô mon Jésus, ce n’est pas le poids de la Croix, mais celui de mes péchés qui Vous a causé tant de souffrances. Par les mérites de cette première chute, préservez-moi du malheur de tomber dans le péché mortel. Je Vous aime, ô Jésus, de tout mon cœur; je me repens de Vous avoir offensé. Ne permettez pas que je Vous offense encore. Donnez-moi de Vous aimer toujours; et ensuite disposez de moi comme il Vous plaira."},{"consider":"Considérez la rencontre du Fils et de la Mère sur ce chemin. Jésus et Marie se regardèrent, et leurs regards furent comme autant de flèches qui transpercèrent leurs Cœurs si tendrement unis.","prayer":"Ô Jésus très aimant, par la douleur que Vous avez éprouvée dans cette rencontre, accordez-moi la grâce d’un amour vraiment dévoué envers votre très sainte Mère. Et Vous, ô ma Reine, qui fûtes accablée de douleur, obtenez-moi par votre intercession un souvenir continuel et tendre de la Passion de votre Fils. Je Vous aime, Jésus mon amour; je me repens de Vous avoir offensé. Ne permettez pas que je Vous offense encore. Donnez-moi de Vous aimer toujours; et ensuite disposez de moi comme il Vous plaira."},{"consider":"Considérez comment les Juifs, voyant Jésus près d’expirer de faiblesse à chaque pas, craignirent qu’Il ne mourût en chemin, tandis qu’ils voulaient Le voir mourir de la mort ignominieuse de la Croix; ils contraignirent donc Simon de Cyrène à porter la Croix derrière Notre-Seigneur.","prayer":"Ô mon très doux Jésus, je ne veux pas refuser la Croix comme le Cyrénéen; je l’accepte, je l’embrasse. J’accepte en particulier la mort que Vous m’avez destinée, avec toutes les douleurs qui pourront l’accompagner; je l’unis à votre mort et je Vous l’offre. Vous êtes mort par amour pour moi; je veux mourir par amour pour Vous et pour Vous plaire. Aidez-moi de votre grâce. Je Vous aime, Jésus mon amour; je me repens de Vous avoir offensé. Ne permettez pas que je Vous offense encore. Donnez-moi de Vous aimer toujours; et ensuite disposez de moi comme il Vous plaira."},{"consider":"Considérez comment la sainte femme nommée Véronique, voyant Jésus si affligé et son visage baigné de sueur et de sang, Lui présenta un linge avec lequel Il essuya son adorable Face, y laissant empreinte son image sacrée.","prayer":"Ô mon Jésus très aimé, votre Face était belle auparavant; mais sur ce chemin les blessures et le sang l’ont entièrement défigurée. Hélas! mon âme aussi était belle lorsqu’elle reçut votre grâce au Baptême; mais je l’ai défigurée par mes péchés. Vous seul, ô mon Rédempteur, pouvez lui rendre sa première beauté. Faites-le par les mérites de votre Passion. Je Vous aime, Jésus mon amour; je me repens de Vous avoir offensé. Ne permettez pas que je Vous offense encore. Donnez-moi de Vous aimer toujours; et ensuite disposez de moi comme il Vous plaira."},{"consider":"Considérez la seconde chute de Jésus sous la Croix, chute qui renouvelle la douleur de toutes les plaies de la tête et des membres de Notre-Seigneur affligé.","prayer":"Ô mon très doux Jésus, combien de fois Vous m’avez pardonné, et combien de fois suis-je retombé dans les mêmes fautes et ai-je recommencé à Vous offenser! Par les mérites de cette nouvelle chute, donnez-moi les secours nécessaires pour persévérer dans votre grâce jusqu’à la mort. Accordez que, dans toutes les tentations qui m’assailliront, je me recommande toujours à Vous. Je Vous aime, Jésus mon amour, de tout mon cœur; je me repens de Vous avoir offensé. Ne permettez pas que je Vous offense encore. Donnez-moi de Vous aimer toujours; et ensuite disposez de moi comme il Vous plaira."},{"consider":"Considérez comment ces femmes, voyant Jésus épuisé et couvert de sang sur son chemin, pleuraient de compassion. Mais Jésus, se tournant vers elles, leur dit: « Ne pleurez pas sur Moi, mais pleurez sur vous-mêmes et sur vos enfants. »","prayer":"Ô Jésus chargé de douleurs, je pleure les offenses que j’ai commises contre Vous, à cause des peines qu’elles ont méritées, mais plus encore à cause du déplaisir qu’elles Vous ont causé, à Vous qui m’avez tant aimé. C’est votre amour, plus que la crainte de l’enfer, qui me fait pleurer mes péchés. Mon Jésus, je Vous aime plus que moi-même; je me repens de Vous avoir offensé. Ne permettez pas que je Vous offense encore. Donnez-moi de Vous aimer toujours; et ensuite disposez de moi comme il Vous plaira."},{"consider":"Considérez la troisième chute de Jésus-Christ. Sa faiblesse était extrême, et excessive la cruauté de ses bourreaux, qui voulaient hâter ses pas alors qu’Il avait à peine la force de se mouvoir.","prayer":"Ô Jésus si cruellement traité, par les mérites de cette faiblesse que Vous avez voulu souffrir sur le chemin du Calvaire, donnez-moi assez de force pour vaincre tout respect humain et toutes mes passions mauvaises, qui m’ont autrefois conduit à mépriser votre amitié. Je Vous aime, Jésus mon amour, de tout mon cœur; je me repens de Vous avoir offensé. Ne permettez pas que je Vous offense encore. Donnez-moi de Vous aimer toujours; et ensuite disposez de moi comme il Vous plaira."},{"consider":"Considérez avec quelle violence les bourreaux dépouillèrent Jésus de ses vêtements. Sa tunique intérieure adhérait à sa chair déchirée, et ils l’arrachèrent avec tant de rudesse qu’ils emportèrent avec elle la peau de ses plaies. Ayez compassion de votre Sauveur ainsi cruellement traité.","prayer":"Ô Jésus innocent, par les mérites de ce tourment, aidez-moi à me dépouiller de toute affection aux choses de la terre, afin que je place tout mon amour en Vous, qui êtes si digne d’être aimé. Je Vous aime, ô Jésus, de tout mon cœur; je me repens de Vous avoir offensé. Ne permettez pas que je Vous offense encore. Donnez-moi de Vous aimer toujours; et ensuite disposez de moi comme il Vous plaira."},{"consider":"Considérez comment Jésus, étendu sur la Croix, ouvre ses mains et offre à son Père éternel le sacrifice de sa vie pour notre salut. Ses bourreaux L’y attachent avec des clous; puis, ayant élevé la Croix, ils Le laissent mourir dans les angoisses sur ce gibet infâme.","prayer":"Ô mon Jésus accablé d’opprobres, attachez mon cœur à vos pieds, afin qu’il y demeure toujours pour Vous aimer et ne Vous quitte jamais. Je Vous aime plus que moi-même; je me repens de Vous avoir offensé. Ne permettez pas que je Vous offense encore. Donnez-moi de Vous aimer toujours; et ensuite disposez de moi comme il Vous plaira."},{"consider":"Considérez Jésus crucifié qui, après trois heures d’agonie sur la Croix, consumé enfin par les douleurs, abandonne son Corps à la mort, incline la tête et rend l’esprit.","prayer":"Ô mon Jésus mourant, je baise avec dévotion la Croix sur laquelle Vous êtes mort par amour pour moi. Par mes péchés, j’ai mérité une mort malheureuse; mais votre mort est mon espérance. Par les mérites de votre mort, accordez-moi la grâce de mourir en embrassant vos pieds et brûlant d’amour pour Vous. Je remets mon âme entre vos mains. Je Vous aime de tout mon cœur; je me repens de Vous avoir offensé. Ne permettez pas que je Vous offense encore. Donnez-moi de Vous aimer toujours; et ensuite disposez de moi comme il Vous plaira."},{"consider":"Considérez comment, après la mort de Notre-Seigneur, deux de ses disciples, Joseph et Nicodème, Le descendirent de la Croix et Le déposèrent dans les bras de sa Mère affligée, qui reçut son Fils mort avec une tendresse inexprimable et Le pressa contre son Cœur.","prayer":"Ô Mère des douleurs, par l’amour que Vous portez à votre Fils, recevez-moi pour votre serviteur et priez-Le pour moi. Et Vous, ô mon Rédempteur, puisque Vous êtes mort pour moi, permettez-moi de Vous aimer; car je ne veux que Vous et rien de plus. Je Vous aime, ô mon Jésus; je me repens de Vous avoir offensé. Ne permettez pas que je Vous offense encore. Donnez-moi de Vous aimer toujours; et ensuite disposez de moi comme il Vous plaira."},{"consider":"Considérez comment les disciples portèrent le Corps de Jésus au lieu de sa sépulture. Sa Mère affligée les accompagna et, de ses propres mains, disposa le Corps de son Fils dans le tombeau. Le sépulcre fut ensuite fermé, et tous se retirèrent.","prayer":"Ô Jésus enseveli, je baise la pierre qui Vous renferme. Mais Vous ressusciterez le troisième jour. Par votre Résurrection, faites, je Vous en supplie, que je ressuscite glorieux avec Vous au dernier jour et que j’aille au ciel, où, toujours uni à Vous, je Vous louerai et Vous aimerai éternellement. Je Vous aime et je me repens de Vous avoir offensé. Ne permettez pas que je Vous offense encore. Donnez-moi de Vous aimer toujours; et ensuite disposez de moi comme il Vous plaira."}]},"exam":{"title":"Ten Commandments","intro":"Review your freely chosen actions and omissions since your last Confession.","sections":[["1 · God first",["Have I neglected prayer or knowingly rejected the faith?","Have I placed superstition, divination, money or approval above trust in God?"]],["2 · Reverence",["Have I used God’s name contemptuously or sworn falsely?","Have I treated sacred things irreverently?"]],["3 · Worship and rest",["Have I deliberately missed Sunday Mass or a binding holy day without a serious reason?","Have I needlessly prevented others from worship or reasonable rest?"]],["4 · Family and authority",["Have I neglected care, respect or just responsibilities within my family?","Have I misused authority, manipulated another person or demanded unjust obedience?"]],["5 · Life and charity",["Have I deliberately harmed someone, encouraged violence or chosen revenge?","Have I neglected reasonable care for life and health, or help I was responsible for giving?"]],["6 · Chastity and fidelity",["Have I freely chosen sexual acts contrary to chastity, pornography or infidelity?","Have I treated another person as an object rather than respected their dignity?"]],["7 · Justice",["Have I stolen, cheated, withheld just payment or misused property entrusted to me?","Have I refused to repair financial harm when able?"]],["8 · Truth",["Have I lied, slandered, gossiped unjustly or betrayed a confidence?","Have I failed to correct a falsehood or restore a reputation I harmed?"]],["9 · Purity of heart",["Have I deliberately cultivated desires contrary to fidelity and chastity?","Distinguish an unwanted thought or temptation from a deliberate choice to entertain it."]],["10 · Detachment",["Have I allowed envy or greed to govern my choices?","Have I resented another person’s good or neglected generosity within my means?"]]]},"examFr":{"intro":"Repassez devant Dieu les actes et omissions librement choisis depuis votre dernière bonne confession.","sections":[["1 · Dieu d’abord",["Ai-je négligé la prière ou rejeté sciemment la foi ?","Ai-je placé la superstition, la divination, l’argent ou l’approbation humaine au-dessus de la confiance en Dieu ?"]],["2 · Révérence",["Ai-je employé le nom de Dieu avec mépris ou fait un faux serment ?","Ai-je traité les choses sacrées sans respect ?"]],["3 · Culte et repos",["Ai-je manqué délibérément la Messe du dimanche ou un jour d’obligation sans raison grave ?","Ai-je empêché sans nécessité d’autres personnes d’accomplir leur devoir religieux ou de prendre un repos raisonnable ?"]],["4 · Famille et autorité",["Ai-je négligé le soin, le respect ou les responsabilités justes dans ma famille ?","Ai-je abusé de mon autorité, manipulé quelqu’un ou exigé une obéissance injuste ?"]],["5 · Vie et charité",["Ai-je volontairement fait du tort à quelqu’un, encouragé la violence ou choisi la vengeance ?","Ai-je négligé le soin raisonnable de la vie et de la santé, ou l’aide que j’avais le devoir de donner ?"]],["6 · Chasteté et fidélité",["Ai-je librement choisi des actes contraires à la chasteté, la pornographie ou l’infidélité ?","Ai-je traité une personne comme un objet au lieu de respecter sa dignité ?"]],["7 · Justice",["Ai-je volé, trompé, retenu un juste salaire ou mal employé un bien qui m’était confié ?","Ai-je refusé de réparer un dommage matériel alors que je le pouvais ?"]],["8 · Vérité",["Ai-je menti, calomnié, médit injustement ou trahi une confidence ?","Ai-je omis de corriger une fausseté ou de réparer une réputation que j’avais lésée ?"]],["9 · Pureté du cœur",["Ai-je volontairement entretenu des désirs contraires à la fidélité et à la chasteté ?","Je distingue une pensée ou tentation non voulue du choix délibéré de l’entretenir."]],["10 · Détachement",["Ai-je laissé l’envie ou l’avidité gouverner mes choix ?","Ai-je regretté le bien d’autrui ou négligé la générosité selon mes moyens ?"]]]}};

